        extents: [{ relOffset: 0, length: primaryPayload.length }],
        propertyIndices: [1, 2],
      },
      {
        itemId: AUX_AUX_ID,
        itemType: "av01",
        hidden: true,
        extents: [
          { relOffset: primaryPayload.length, length: auxPayload.length },
