  it("free and skip boxes at the top level parse", async () => {
    const freeBox = box("free", Buffer.alloc(4));
    const skipBox = box("skip", Buffer.alloc(4));
    const mdat = mdatBox(Buffer.from([1, 2, 3, 4]));
    const file = Buffer.concat([
      minimalFtyp(),
