    Buffer.from("C2PA-CANARY-62-06-HEIC", "ascii"),
    Buffer.alloc(32 - "C2PA-CANARY-62-06-HEIC".length, 0x00),
  ]);

  const tiff = createMinimalExif({ orientation: 1 });
