          {
            relOffset: primaryPayload.length + auxPayload.length,
            length: exifPayload.length,
          },
        ],
      },
      {
        itemId: HEIC_AUX_XMP_ID,
        itemType: "mime",
        contentType: "application/rdf+xml",
        extents: [
          {
