});

// --- CR-01 code review fix pass (62-13): k's iref rewrite must match the qualifying `cdsc`
// record, not every record whose from-item is k --------------------------------------------------
//
// 62-REVIEW.md CR-01: `plan.ts`/`verify.ts` rewrote EVERY iref record whose `fromItemId` is k to
// `toItemIds: [primaryItemId]`, not only the single qualifying `cdsc` record (the one whose
// to-list contains the primary -- the record that made k a candidate at all, D-13). A second,
// unrelated record from k (here: a second `cdsc` to a different surviving item) had its real
// target silently replaced with the primary. Admission's Rule 6 (`removable-item-referenced`)
// guarantees every iref to-target is a surviving item, so no removed-target handling is ever
// needed for a non-qualifying record from k -- it is always copied verbatim once the qualifying
// record is identified correctly.

const CR01_PRIMARY_ID = 1;
const CR01_OTHER_SURVIVING_ID = 3;
const CR01_K_ID = 2;

/** Primary (1) + a second surviving item (3, unrelated to k) + k (2, a non-emptied Exif item
 * whose FIRST `cdsc` record points at the primary, D-13) carrying a SECOND iref record (another
 * `cdsc`, to item 3, which does not describe the primary at all). `preserveOrientation: true`
 * with a requested Orientation tag present makes k survive as the minimal Exif item (D-13's
 * "write rule"), so the writer's iref rewrite for k is actually exercised. */
function buildKWithSecondIrefRecordFixture(brand: "heic" | "avif"): Buffer {
  const majorBrand = brand;
  const compatibleBrands =
    brand === "heic" ? ["mif1", "heic"] : ["mif1", "avif"];
  const itemType = brand === "heic" ? "hvc1" : "av01";
  const primaryPayload = Buffer.from("cr01-primary", "ascii");
  const otherPayload = Buffer.from("cr01-other", "ascii");
  const exifPayload = Buffer.concat([
    Buffer.alloc(4),
    createMinimalExif({ orientation: 1 }),
  ]);
  return assembleHeif({
    majorBrand,
    compatibleBrands,
    primaryItemId: CR01_PRIMARY_ID,
    items: [
      {
        itemId: CR01_PRIMARY_ID,
        itemType,
        extents: [{ relOffset: 0, length: primaryPayload.length }],
      },
      {
        itemId: CR01_OTHER_SURVIVING_ID,
        itemType,
        extents: [
          { relOffset: primaryPayload.length, length: otherPayload.length },
        ],
      },
      {
        itemId: CR01_K_ID,
        itemType: "Exif",
        hidden: true,
        extents: [
          {
            relOffset: primaryPayload.length + otherPayload.length,
            length: exifPayload.length,
          },
        ],
      },
    ],
    // The FIRST record (cdsc, k -> primary) is the qualifying record (D-13). The SECOND record
    // (cdsc, k -> the other surviving item) is unrelated -- it never describes the primary, so k
    // qualifies on the first record alone, and the second record must survive untouched.
    refs: [
      { type: "cdsc", fromItemId: CR01_K_ID, toItemIds: [CR01_PRIMARY_ID] },
      {
        type: "cdsc",
        fromItemId: CR01_K_ID,
        toItemIds: [CR01_OTHER_SURVIVING_ID],
      },
    ],
    mdatPayload: Buffer.concat([primaryPayload, otherPayload, exifPayload]),
    ilocWidths: { offsetSize: 4, lengthSize: 4, baseOffsetSize: 4 },
    twoPass: true,
  });
}

describe("CR-01 code review fix pass (62-13): k's iref rewrite matches the qualifying cdsc record only", () => {
  it.each(["heic", "avif"] as const)(
    "%s: k's own unrelated second iref record (not the qualifying cdsc) survives with its real target, only the qualifying cdsc record is reduced to [pitm]",
    async (brand) => {
      const bytes = buildKWithSecondIrefRecordFixture(brand);
      const directory = await freshDirectory();
      const sourcePath = join(directory, `source.${brand}`);
      const destinationPath = join(directory, `destination.${brand}`);
      await writeFile(sourcePath, bytes);

      const restore = setRegisteredHandlersForTests([
        createIsobmffWriterHandlerForTests(brand),
      ]);
      try {
        const sanitized = await sanitizeFile({
          sourcePath,
          destinationPath,
          preserveOrientation: true,
          preserveColorProfile: false,
          preserveTimestamps: false,
          preserveResolution: false,
        });
        expect(sanitized.ok).toBe(true);
        if (!sanitized.ok) {
          throw new Error(
            `sanitizeFile failed: ${JSON.stringify(sanitized.error)}`,
          );
        }

        const destinationBytes = await readFile(destinationPath);
        const destinationInventory = inventoryIsobmff(destinationBytes);

        const qualifyingRecord = destinationInventory.references.find(
          (reference) =>
            reference.type === "cdsc" &&
            reference.from === CR01_K_ID &&
            reference.to.length === 1 &&
            reference.to[0] === CR01_PRIMARY_ID,
        );
        expect(qualifyingRecord).toBeDefined();

        // CR-01: the second record from k must still name its real target (the other surviving
        // item), not the primary. Before the fix, the blanket rewrite replaced its to-list with
        // [primary] too, silently losing the real reference.
        const secondRecord = destinationInventory.references.find(
          (reference) =>
            reference.type === "cdsc" &&
            reference.from === CR01_K_ID &&
            reference.to.length === 1 &&
            reference.to[0] === CR01_OTHER_SURVIVING_ID,
        );
        expect(secondRecord).toBeDefined();

        // Exactly two records from k survive (never collapsed into one).
        const recordsFromK = destinationInventory.references.filter(
          (reference) => reference.from === CR01_K_ID,
        );
        expect(recordsFromK.length).toBe(2);
      } finally {
        restore();
      }
    },
  );

  it("heic: tampering k's second iref record to the blanket-rewrite shape (the pre-fix bug, replayed as a mutant) is caught by verify", async () => {
    const bytes = buildKWithSecondIrefRecordFixture("heic");
    const directory = await freshDirectory();
    const sourcePath = join(directory, "source.heic");
    const destinationPath = join(directory, "destination.heic");
    await writeFile(sourcePath, bytes);

    const inner = createIsobmffWriterHandlerForTests("heic");
    const mutant = createPlanMutantHandler(
      inner,
      mutateIrefSquashSecondRecordFromK,
    );
    const restore = setRegisteredHandlersForTests([mutant]);
    try {
      const sanitized = await sanitizeFile({
        sourcePath,
        destinationPath,
        preserveOrientation: true,
        preserveColorProfile: false,
        preserveTimestamps: false,
        preserveResolution: false,
      });
      expect(sanitized.ok).toBe(false);
    } finally {
      restore();
    }
  });
});

// --- WR-01 code review fix pass (62-13): verify must recompute the WHOLE surviving `ipco`
// payload independently, not only each surviving item's own associated properties -------------
//
// 62-REVIEW.md WR-01: with `preserveColorProfile: false`, verify checked each surviving item's
// associated property bytes and the absence of removed ICC bytes, but never recomputed "source
// properties in order minus the removed indices" and compared the WHOLE ipco payload. A property
// referenced by no `ipma` entry at all (D-34's orphan shape, e.g. `udes`) survives ICC removal
// unaffected -- its bytes were never checked by anything.

const WR01_PRIMARY_ID = 1;
const WR01_ORPHAN_TYPE = "udes";

/** One surviving primary associated with `ispe` + a `colr prof` (removed under
 * `preserveColorProfile: false`), plus a THIRD ipco property (`udes`) that no item's `ipma`
 * entry references at all -- the orphan this fixture exists to protect. */
function buildOrphanIpcoPropertyFixture(): Buffer {
  const primaryPayload = Buffer.from("wr01-primary", "ascii");
  const orphanPayload = Buffer.from("WR01-ORPHAN-UDES-PAYLOAD", "ascii");
  return assembleHeif({
    majorBrand: "heic",
    compatibleBrands: ["mif1", "heic"],
    primaryItemId: WR01_PRIMARY_ID,
    items: [
      {
        itemId: WR01_PRIMARY_ID,
        itemType: "hvc1",
        extents: [{ relOffset: 0, length: primaryPayload.length }],
        propertyIndices: [1, 2],
      },
    ],
    properties: [
      ispe(32, 32),
      box(
        "colr",
        Buffer.concat([
          Buffer.from("prof", "ascii"),
          Buffer.from([0xaa, 0xbb]),
        ]),
      ),
      box(WR01_ORPHAN_TYPE, orphanPayload),
    ],
    mdatPayload: primaryPayload,
    twoPass: true,
  });
}

describe("WR-01 code review fix pass (62-13): verify recomputes the whole surviving ipco payload", () => {
  it("heic: corrupting an orphan ipco property no ipma entry references is caught by verify", async () => {
    const bytes = buildOrphanIpcoPropertyFixture();
    const directory = await freshDirectory();
    const sourcePath = join(directory, "source.heic");
    const destinationPath = join(directory, "destination.heic");
    await writeFile(sourcePath, bytes);

    const inner = createIsobmffWriterHandlerForTests("heic");
    const mutant = createPlanMutantHandler(
      inner,
      mutateIpcoCorruptOrphanProperty(WR01_ORPHAN_TYPE),
    );
    const restore = setRegisteredHandlersForTests([mutant]);
    try {
      const sanitized = await sanitizeFile({
        sourcePath,
        destinationPath,
        preserveOrientation: false,
        preserveColorProfile: false,
        preserveTimestamps: false,
        preserveResolution: false,
      });
      expect(sanitized.ok).toBe(false);
    } finally {
      restore();
    }
  });
});

tests/isobmff_generator.test.ts.source:
// tests/isobmff-support/generator.ts coverage (BMF-03/BMF-04, D-19, Locked Decision 18): proves
// the shared ISOBMFF property generator's per-arm floors and agreement with the real
// `admitIsobmff` classifier, and that it is NOT wired into the qualification kit this phase.
import { existsSync, readFileSync } from "node:fs";
import { mkdtemp, open, rm } from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import fc from "fast-check";
import { afterEach, describe, expect, it } from "vitest";
import { admitIsobmff } from "../src/isobmff/admission.js";
import { C2PA_UUID_USERTYPE } from "../src/isobmff/boxes.js";
import {
  DECLINE_CLASS_TO_KIND,
  ISOBMFF_DECLINE_CLASSES,
  IsobmffStructureError,
  type IsobmffDeclineClass,
} from "../src/isobmff/errors.js";
import {
  assertFloors,
  countSample,
  createCounters,
} from "./qualification/kit/floors.js";
import { assertPlanted } from "./qualification/kit/generators.js";
import {
  GENERATOR_C2PA_USERTYPE,
  isMetadataSample,
  isobmffArmSampleArbitrary,
  isobmffArmSampleArbitraryWithoutMetadataArm,
  isobmffMetadataGenerator,
  ISOBMFF_ARM_FLOORS,
} from "./isobmff-support/generator.js";
import { avifMetadataGenerator } from "./qualification/avif/generators.js";
import { heicMetadataGenerator } from "./qualification/heic/generators.js";

const PROJECT_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));

const cleanupDirectories: string[] = [];

afterEach(async () => {
  while (cleanupDirectories.length > 0) {
    const directory = cleanupDirectories.pop();
    if (directory !== undefined) {
      await rm(directory, { recursive: true, force: true });
    }
  }
});

async function withTempFile<T>(
  bytes: Buffer,
  fn: (handle: FileHandle, size: number) => Promise<T>,
): Promise<T> {
  const directory = await mkdtemp(
    join(tmpdir(), "exifcleaner-isobmff-generator-"),
  );
  cleanupDirectories.push(directory);
  const path = join(directory, "sample.heic");
  const writeHandle = await open(path, "w");
  try {
    await writeHandle.write(bytes, 0, bytes.length, 0);
  } finally {
    await writeHandle.close();
  }
  const readHandle = await open(path, "r");
  try {
    return await fn(readHandle, bytes.length);
  } finally {
    await readHandle.close();
  }
}

describe("tests/isobmff-support/generator.ts exports", () => {
  it("exports isobmffMetadataGenerator, isobmffArmSampleArbitrary, ISOBMFF_ARM_FLOORS", () => {
    expect(isobmffMetadataGenerator.format).toBe("isobmff");
    expect(isobmffMetadataGenerator.metadataKinds).toEqual([
      "EXIF",
      "XMP",
      "ICC",
      "C2PA",
    ]);
    expect(typeof isobmffArmSampleArbitrary).toBe("function");
    expect(typeof ISOBMFF_ARM_FLOORS).toBe("object");
  });

  it("the generator's C2PA uuid usertype literal equals C2PA_UUID_USERTYPE from src/isobmff/boxes.ts", () => {
    // The generator cannot import src/isobmff/ (isolation rule): this unrestricted test is the
    // equality check that keeps its duplicated literal honest.
    expect(GENERATOR_C2PA_USERTYPE).toBe(C2PA_UUID_USERTYPE);
  });

  it("every IsobmffHazardClass literal the generator uses is a real IsobmffDeclineClass", () => {
    // The generator cannot import IsobmffDeclineClass (isolation rule) -- it hardcodes literal
    // strings instead. This test, unrestricted, proves those literals still name real classes.
    const hazardLiterals: readonly IsobmffDeclineClass[] = [
      "unknown-item-type",
      "construction-method-2",
      "external-data-reference",
      "removable-item-referenced",
    ];
    for (const literal of hazardLiterals) {
      expect(ISOBMFF_DECLINE_CLASSES).toContain(literal);
    }
  });
});

describe("the generator is not wired into QUALIFICATION_FORMATS (D-19)", () => {
  it("tests/qualification/formats.ts has no isobmff key", () => {
    const source = readFileSync(
      join(PROJECT_ROOT, "tests/qualification/formats.ts"),
      "utf8",
    );
    expect(/^\s*isobmff:/mu.test(source)).toBe(false);
  });

  it("tests/qualification/isobmff/ does not exist", () => {
    expect(existsSync(join(PROJECT_ROOT, "tests/qualification/isobmff"))).toBe(
      false,
    );
  });
});

// The qualification fixed seed and run count (FC_SEED/FC_RUNS, 62.1-06 / D-28).
const FC_SEED = 460046;
const FC_RUNS = 200;

describe("isobmffArmSampleArbitrary meets ISOBMFF_ARM_FLOORS and agrees with admitIsobmff", () => {
  it(`every arm clears its floor over ${FC_RUNS} runs (seed ${FC_SEED}), per brand`, () => {
    for (const brand of ["heic", "avif"] as const) {
      const counters = createCounters();
      fc.assert(
        fc.property(isobmffArmSampleArbitrary(brand), ({ arms }) => {
          countSample(counters, arms);
        }),
        { seed: FC_SEED, numRuns: FC_RUNS },
      );
      assertFloors(counters, ISOBMFF_ARM_FLOORS);
    }
  });

  it("every non-hazard sample admits with its canaries present (a mutation sample keeps its surviving canaries verbatim) and Exif/XMP removable; every hazard sample declines with its own class", async () => {
    for (const brand of ["heic", "avif"] as const) {
      await fc.assert(
        fc.asyncProperty(
          isobmffArmSampleArbitrary(brand),
          async (armSample) => {
            const { sample, arms, hazardClass } = armSample;

            if (arms.includes("hazard")) {
              if (hazardClass === undefined) {
                throw new Error("hazard arm sample is missing its hazardClass");
              }
              let caught: unknown;
              try {
                await withTempFile(sample.bytes, (handle, size) =>
                  admitIsobmff(handle, size),
                );
              } catch (error) {
                caught = error;
              }
              if (!(caught instanceof IsobmffStructureError)) {
                throw new Error(
                  `hazard sample (class ${hazardClass}) did not decline with an IsobmffStructureError`,
                );
              }
              expect(caught.declineClass).toBe(hazardClass);
              expect(caught.kind).toBe(DECLINE_CLASS_TO_KIND[hazardClass]);
              return;
            }

            assertPlanted(sample.bytes, sample.planted);
            // A mutation sample is admitted or refused: only its planted canaries are checked.
            if (arms.includes("mutation")) return;
            const admission = await withTempFile(sample.bytes, (handle, size) =>
              admitIsobmff(handle, size),
            );
            const exifItems = admission.model.items.filter(
              (item) => item.type === "Exif",
            );
            const xmpItems = admission.model.items.filter(
              (item) => item.type === "mime",
            );
            expect(exifItems.length).toBeGreaterThan(0);
            expect(xmpItems.length).toBeGreaterThan(0);
            for (const item of [...exifItems, ...xmpItems]) {
              expect(admission.classification.removableItemIds).toContain(
                item.id,
              );
            }
          },
        ),
        { seed: FC_SEED, numRuns: FC_RUNS },
      );
    }
  }, 30_000);
});

// IN-01 (62.1-06): QUALIFICATION_FORMATS wires one generator per format, so a sample drawn from
// `isobmffArmSampleArbitrary("heic")` must actually be a heic file. Read the ftyp box directly
// here (not through the engine or the builder) so the brand claim has an independent check.

function ftypBrandOf(bytes: Buffer): "heic" | "avif" | "other" {
  if (bytes.length < 16 || bytes.toString("latin1", 4, 8) !== "ftyp") {
    return "other";
  }
  const size = bytes.readUInt32BE(0);
  if (size < 16 || size > bytes.length || (size - 16) % 4 !== 0) {
    return "other";
  }
  const brands = [bytes.toString("latin1", 8, 12)];
  for (let offset = 16; offset < size; offset += 4) {
    brands.push(bytes.toString("latin1", offset, offset + 4));
  }
  const isHeic = brands.some((brand) => brand === "heic" || brand === "heix");
  const isAvif = brands.some((brand) => brand === "avif" || brand === "avis");
  if (isHeic && !isAvif) return "heic";
  if (isAvif && !isHeic) return "avif";
  return "other";
}

describe("isobmffArmSampleArbitrary(brand) emits only that brand (IN-01)", () => {
  it("ftypBrandOf reads heic and avif ftyp boxes and rejects anything else (control)", () => {
    const ftyp = (major: string, ...compatible: string[]): Buffer => {
      const body = Buffer.from(
        [major, "\0\0\0\0", ...compatible].join(""),
        "latin1",
      );
      const header = Buffer.alloc(8);
      header.writeUInt32BE(8 + body.length, 0);
      header.write("ftyp", 4, "latin1");
      return Buffer.concat([header, body]);
    };
    expect(ftypBrandOf(ftyp("heic", "mif1", "heic"))).toBe("heic");
    expect(ftypBrandOf(ftyp("avif", "mif1", "avif"))).toBe("avif");
    expect(ftypBrandOf(ftyp("mif1", "heic", "avif"))).toBe("other");
    expect(ftypBrandOf(ftyp("mp42", "isom"))).toBe("other");
    expect(ftypBrandOf(Buffer.from("not a box at all"))).toBe("other");
  });

  for (const brand of ["heic", "avif"] as const) {
    it(`every non-hazard sample from isobmffArmSampleArbitrary("${brand}") classifies as ${brand} (seed ${FC_SEED}, ${FC_RUNS} samples)`, () => {
      const samples = fc.sample(
        isobmffArmSampleArbitrary(brand).filter(isMetadataSample),
        { seed: FC_SEED, numRuns: FC_RUNS },
      );
      expect(samples).toHaveLength(FC_RUNS);
      const misclassified = samples
        .map((armSample) => ftypBrandOf(armSample.sample.bytes))
        .filter((classified) => classified !== brand);
      expect(misclassified).toEqual([]);
    });
  }
});

describe("heicMetadataGenerator and avifMetadataGenerator (QUA-03, one generator per format)", () => {
  for (const [brand, generator] of [
    ["heic", heicMetadataGenerator],
    ["avif", avifMetadataGenerator],
  ] as const) {
    it(`${brand}MetadataGenerator names ${brand}, plants EXIF and XMP (plus ICC and C2PA where the file carries them), and emits only ${brand} files`, () => {
      expect(generator.format).toBe(brand);
      expect(generator.metadataKinds).toEqual(["EXIF", "XMP", "ICC", "C2PA"]);
      const samples = fc.sample(generator.arbitrary(), {
        seed: FC_SEED,
        numRuns: FC_RUNS,
      });
      expect(samples).toHaveLength(FC_RUNS);
      for (const sample of samples) {
        expect(ftypBrandOf(sample.bytes)).toBe(brand);
        const kinds = sample.planted.map((item) => item.kind);
        expect(kinds.slice(0, 2)).toEqual(["EXIF", "XMP"]);
        expect(
          kinds.slice(2).every((kind) => kind === "ICC" || kind === "C2PA"),
        ).toBe(true);
        expect(new Set(kinds).size).toBe(kinds.length);
        assertPlanted(sample.bytes, sample.planted);
      }
    });
  }
});

describe("ISOBMFF_ARM_FLOORS edges (QUA-03)", () => {
  it("adjacency: assertFloors passes at exactly the floor and fails at floor - 1 (hand-built counter)", () => {
    const atFloor = { ...ISOBMFF_ARM_FLOORS };
    expect(() => assertFloors(atFloor, ISOBMFF_ARM_FLOORS)).not.toThrow();
    for (const [arm, floor] of Object.entries(ISOBMFF_ARM_FLOORS)) {
      const belowFloor = { ...ISOBMFF_ARM_FLOORS, [arm]: floor - 1 };
      expect(() => assertFloors(belowFloor, ISOBMFF_ARM_FLOORS)).toThrow(
        `${arm}: measured ${floor - 1}, required at least ${floor}`,
      );
    }
  });

  it("empty arm: a generator variant with no Exif/XMP arm fails the floor assertion itself (D-21 negative control (3))", () => {
    for (const brand of ["heic", "avif"] as const) {
      const counters = createCounters();
      for (const { arms } of fc.sample(
        isobmffArmSampleArbitraryWithoutMetadataArm(brand),
        { seed: FC_SEED, numRuns: FC_RUNS },
      )) {
        expect(arms).toEqual(["hazard"]);
        countSample(counters, arms);
      }
      expect(counters["hazard"]).toBe(FC_RUNS);
      expect(() => assertFloors(counters, ISOBMFF_ARM_FLOORS)).toThrow(
        `xmp: measured 0, required at least ${ISOBMFF_ARM_FLOORS.xmp}`,
      );
    }
  });

  it("ordering: the same seed replays the identical byte sequence per brand, and a different seed differs", () => {
    const bytesAt = (brand: "heic" | "avif", seed: number): string[] =>
      fc
        .sample(isobmffArmSampleArbitrary(brand), {
          seed,
          numRuns: FC_RUNS,
        })
        .map(({ sample }) => sample.bytes.toString("hex"));
    for (const brand of ["heic", "avif"] as const) {
      const first = bytesAt(brand, FC_SEED);
      expect(bytesAt(brand, FC_SEED)).toEqual(first);
      expect(bytesAt(brand, FC_SEED + 1)).not.toEqual(first);
    }
  });
});

