      );
      await writeFile(path, bytes);
      await expectAdmissionDecline(
        path,
        "item-graph-invalid",
        "malformed-file",
      );
    });
  });

  describe("dinf/dref self-contained rule (D-17, inferred)", () => {
    function urlEntry(
      flags: number,
