import type { FileHandle } from "node:fs/promises";
import { readExactly } from "./boxes.js";
import { SEQUENCE_BRANDS } from "./brand.js";
import {
  DEFAULT_ISOBMFF_CAPS,
  IsobmffBudget,
  type IsobmffCaps,
} from "./caps.js";
import { IsobmffStructureError, type IsobmffDeclineClass } from "./errors.js";
import { parseIsobmff, type IsobmffModel, type IsobmffRange } from "./parse.js";
import {
  parseExif,
  readIfd0Resolution,
  type MinimalExifResolution,
} from "../metadata/exif.js";
import { parseIcc } from "../metadata/icc.js";
import { parseXmp } from "../metadata/xmp.js";
import type {
  FormatAdmission,
  OrientationState,
} from "../admission/handler.js";
import type { MetadataEntry, MetadataWarning } from "../types.js";

// D3/D5 admission classifier (BMF-04): joins the validated item graph (61-07) with the D3
// removable/surviving rules and the D5 safety rules into one `FormatAdmission`-shaped result.
// `classifyIsobmffModel` is pure over an already-parsed `IsobmffModel` -- it never reads a byte
// itself -- so every rule can be proven with hand-built models/fixtures without touching a file
// handle. `admitIsobmff` is the only function in this module that reads bytes outside `meta`: it
// reads exactly the non-emptied removable items' own extents, each guarded by
// `budget.consumeBuffered` before the matching `readExactly` (T-61-25).

/** Restates the base `FormatAdmission` namespace union (D-15); see handler.ts. */
type IsobmffMetadataNamespace =
  "EXIF" | "XMP" | "ICC" | "PNG" | "C2PA" | "JPEG";

/** D3/D7: image item types this engine preserves verbatim, never decodes. */
export const PRESERVED_ITEM_TYPES: ReadonlySet<string> = new Set([
  "hvc1",
  "av01",
  "grid",
  "iden",
  "iovl",
  "tmap",
]);

/** D-07: the only `mime` content types admitted as a removable XMP item. */
export const XMP_CONTENT_TYPES: readonly string[] = ["application/rdf+xml"];

/**
 * BMF-03: the fixed rule order `classifyIsobmffModel` evaluates in, after every parse-time
 * decline (box framing, cap breaches, item-graph validity -- all already thrown by the time a
 * caller has an `IsobmffModel` to pass in). Within each rule, items are visited in `iinf`
 * declaration order (`model.items`'s own order, per 61-07); the first violation is thrown.
 */
export const DECLINE_RULE_ORDER: readonly IsobmffDeclineClass[] = Object.freeze(
  [
    "sequence-brand",
    "unknown-item-type",
    "construction-method-2",
    "external-data-reference",
    "removable-item-in-idat",
    "removable-item-referenced",
    "surviving-offset-width-zero",
    "surviving-zero-length-extent",
    "extent-outside-mdat",
    "removable-extent-overlap",
  ],
);

export interface IsobmffDisposition {
  readonly removableItemIds: readonly number[];
  /** Subset of `removableItemIds` whose extents are all length 0 (or `extent_count` 0, D-10a):
   * admitted, but removing them writes zero bytes. */
  readonly emptiedItemIds: readonly number[];
  readonly survivingItemIds: readonly number[];
  /** Top-level boxes admitted as removable (currently: the C2PA `uuid` box, D5). */
  readonly removableTopLevel: readonly IsobmffRange[];
}

export interface IsobmffAdmission extends FormatAdmission {
  readonly model: IsobmffModel;
  readonly classification: IsobmffDisposition;
  /**
   * D-13 source item k: the first Exif item, in `iinf` order, that is not emptied and has a
   * `cdsc` reference whose to-list contains `model.primaryItemId`. `undefined` when no item
   * qualifies (no Exif item describes the primary, or the only such item is emptied).
   */
  readonly exifSourceItemId: number | undefined;
  /** The IFD0 resolution read from k's own Exif payload only, or `undefined`. */
  readonly sourceResolution: MinimalExifResolution | undefined;
}

/**
 * D-13 source item k: walk `model.items` in `iinf` declaration order and return the id of the
 * first item that is `type === "Exif"`, not emptied (`classification.emptiedItemIds`), and is the
 * from-item of a `cdsc` reference in `model.references` whose `toItemIds` include
 * `model.primaryItemId`. Orientation and resolution must be read only from this item -- an Exif
 * item that describes an auxiliary or thumbnail image (a `cdsc` to-list that never contains
 * `pitm`) must never contribute either value (Phase 61 defect, fixed here).
 */
function findExifSourceItemId(
  model: IsobmffModel,
  classification: IsobmffDisposition,
): number | undefined {
  const emptied = new Set(classification.emptiedItemIds);
  const describesPrimary = new Set(
    model.references
      .filter(
        (reference) =>
          reference.type === "cdsc" &&
          reference.toItemIds.includes(model.primaryItemId),
      )
      .map((reference) => reference.fromItemId),
  );
  for (const item of model.items) {
    if (item.type !== "Exif") continue;
    if (emptied.has(item.id)) continue;
    if (!describesPrimary.has(item.id)) continue;
    return item.id;
  }
  return undefined;
}

/**
 * Add two independently-`MAX_SAFE_INTEGER`-bounded offsets, declining `extent-outside-mdat`
 * rather than silently losing precision if their sum would exceed `Number.isSafeInteger` (WR-01,
 * code review 2026-10-01). `item.baseOffset` and `extent.offset`/`extent.length` are each
 * validated individually by `readSizedUint` (iloc.ts), but their sum is not -- this is the single
 * choke point every such sum in this module must route through.
 */
function addSafeOffsets(a: number, b: number, context: string): number {
  const sum = a + b;
  if (!Number.isSafeInteger(sum)) {
    throw new IsobmffStructureError(
      "extent-outside-mdat",
      `${context}: offset arithmetic (${a} + ${b}) exceeds safe integer precision.`,
    );
  }
  return sum;
}

function mdatBounds(
  model: IsobmffModel,
): { readonly start: number; readonly end: number } | undefined {
  const range = model.mdatRanges[0];
  return range === undefined
    ? undefined
    : { start: range.offset, end: range.offset + range.length };
}

/**
 * Pure classifier over an already-parsed `IsobmffModel` (BMF-03/BMF-04). Throws
 * `IsobmffStructureError` for the first `DECLINE_RULE_ORDER` violation (iinf order within each
 * rule), else returns the admitted disposition.
 */
export function classifyIsobmffModel(
  model: IsobmffModel,
  fileSize: number,
): IsobmffDisposition {
  // Rule 1: sequence-brand. D-18's brand classifier already declines a magic-buffer-visible
  // msf1/avis brand before a handler is ever selected; this re-checks the fully parsed brand set
  // (which may include compatible brands past the 256-byte magic window) as defense in depth.
  const brands = new Set<string>([model.majorBrand, ...model.compatibleBrands]);
  for (const brand of brands) {
    if (SEQUENCE_BRANDS.has(brand)) {
      throw new IsobmffStructureError(
        "sequence-brand",
        `Brand "${brand}" is an image-sequence brand, never admitted as a still item file.`,
      );
    }
  }

  // Rule 2: unknown-item-type. Classifies every item as removable or surviving, in iinf order.
  const kinds = new Map<number, "removable" | "surviving">();
  for (const item of model.items) {
    if (item.type === "Exif") {
      kinds.set(item.id, "removable");
      continue;
    }
    if (item.type === "mime") {
      const hasEncoding =
        item.contentEncoding !== undefined && item.contentEncoding !== "";
      if (
        item.contentType !== undefined &&
        XMP_CONTENT_TYPES.includes(item.contentType) &&
        !hasEncoding
      ) {
        kinds.set(item.id, "removable");
        continue;
      }
      throw new IsobmffStructureError(
        "unknown-item-type",
        // Stryker disable next-line StringLiteral: unobservable-message — MIME description flows only to StructureError message; kind and declineClass are separate.
        `mime item ${item.id} (content_type ${JSON.stringify(item.contentType)}` +
          // Stryker disable next-line StringLiteral: unobservable-message — MIME description flows only to StructureError message; kind and declineClass are separate.
          `${hasEncoding ? ", content_encoding present" : ""}) is not an admitted XMP shape.`,
      );
    }
    if (PRESERVED_ITEM_TYPES.has(item.type)) {
      kinds.set(item.id, "surviving");
      continue;
    }
    throw new IsobmffStructureError(
      "unknown-item-type",
      `Item ${item.id} has type "${item.type}", which is not admitted.`,
    );
  }

  // Rule 3: construction-method-2.
  for (const item of model.items) {
    if (item.constructionMethod === 2) {
      throw new IsobmffStructureError(
        "construction-method-2",
        `Item ${item.id} uses construction_method 2, which is not admitted.`,
      );
    }
  }

  // Rule 4: external-data-reference.
  for (const item of model.items) {
    if (item.dataReferenceIndex !== 0) {
      throw new IsobmffStructureError(
        "external-data-reference",
        `Item ${item.id} has a non-zero data_reference_index (external data).`,
      );
    }
  }

  // Rule 5: removable-item-in-idat (D3).
  for (const item of model.items) {
    if (kinds.get(item.id) === "removable" && item.constructionMethod !== 0) {
      throw new IsobmffStructureError(
        "removable-item-in-idat",
        `Removable item ${item.id} uses construction_method ${item.constructionMethod}, not 0.`,
      );
    }
  }

  // Rule 6: removable-item-referenced (D-08). `to_item_ID` only -- a removable item's own `cdsc`
  // *from* the primary is normal and never checked here.
  const toTargets = new Set<number>();
  for (const reference of model.references) {
    for (const toId of reference.toItemIds) toTargets.add(toId);
  }
  const groupMembers = new Set<number>();
  for (const group of model.groups) {
    for (const entityId of group.entityIds) groupMembers.add(entityId);
  }
  for (const item of model.items) {
    if (kinds.get(item.id) !== "removable") continue;
    if (
      toTargets.has(item.id) ||
      item.id === model.primaryItemId ||
      groupMembers.has(item.id)
    ) {
      throw new IsobmffStructureError(
        "removable-item-referenced",
        `Removable item ${item.id} is referenced as an iref to-target, pitm, or grpl member.`,
      );
    }
  }

  // Rule 7: surviving-offset-width-zero.
  const offsetSize = model.iloc?.offsetSize ?? 0;
  for (const item of model.items) {
    if (
      kinds.get(item.id) === "surviving" &&
      item.constructionMethod === 0 &&
      offsetSize === 0
    ) {
      throw new IsobmffStructureError(
        "surviving-offset-width-zero",
        `Surviving item ${item.id} is construction_method 0 but iloc offset_size is 0.`,
      );
    }
  }

  // Rule 8: surviving-zero-length-extent.
  for (const item of model.items) {
    if (kinds.get(item.id) !== "surviving") continue;
    if (
      item.extents.length === 0 ||
      item.extents.some((extent) => extent.length === 0)
    ) {
      throw new IsobmffStructureError(
        "surviving-zero-length-extent",
        `Surviving item ${item.id} has no extents or a zero-length extent.`,
      );
    }
  }

  // Rule 9: extent-outside-mdat. D-10a: a length-0 cm=0 extent is admitted when its offset is
  // in-bounds (inside the single mdat payload, inclusive of its end, or equal to the file's own
  // size); any other length-0 offset, or any non-zero-length extent that does not fit entirely
  // inside its backing store, declines.
  const mdat = mdatBounds(model);
  const idat = model.idatRange;
  for (const item of model.items) {
    for (const extent of item.extents) {
      if (item.constructionMethod === 1) {
        if (idat === undefined) {
          throw new IsobmffStructureError(
            "extent-outside-mdat",
            `Item ${item.id} is construction_method 1 but meta has no idat.`,
          );
        }
        const start = addSafeOffsets(
          item.baseOffset,
          extent.offset,
          // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
          `Item ${item.id}'s idat extent start`,
        );
        const end = addSafeOffsets(
          start,
          extent.length,
          // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
          `Item ${item.id}'s idat extent end`,
        );
        if (start < 0 || end > idat.length) {
          throw new IsobmffStructureError(
            "extent-outside-mdat",
            `Item ${item.id}'s idat extent [${start}, ${end}) is outside idat (length ${idat.length}).`,
          );
        }
        continue;
      }

      const start = addSafeOffsets(
        item.baseOffset,
        extent.offset,
        // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
        `Item ${item.id}'s extent start`,
      );
      if (extent.length === 0) {
        const insideMdat =
          mdat !== undefined && start >= mdat.start && start <= mdat.end;
        const atFileEnd = start === fileSize;
        if (!insideMdat && !atFileEnd) {
          throw new IsobmffStructureError(
            "extent-outside-mdat",
            `Item ${item.id}'s zero-length extent at offset ${start} is neither inside mdat nor at the file's end.`,
          );
        }
        continue;
      }

      const end = addSafeOffsets(
        start,
        extent.length,
        // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
        `Item ${item.id}'s extent end`,
      );
      if (mdat === undefined || start < mdat.start || end > mdat.end) {
        throw new IsobmffStructureError(
          "extent-outside-mdat",
          `Item ${item.id}'s extent [${start}, ${end}) is outside the single mdat payload.`,
        );
      }
    }
  }

  // Rule 10: removable-extent-overlap. Only cm=0, non-zero-length extents participate (D-10a:
  // length-0 extents never overlap); surviving-versus-surviving overlap is never checked.
  interface AbsoluteExtent {
    readonly start: number;
    readonly end: number;
    readonly itemId: number;
  }
  const survivingRanges: AbsoluteExtent[] = [];
  for (const item of model.items) {
    if (kinds.get(item.id) !== "surviving" || item.constructionMethod !== 0) {
      continue;
    }
    for (const extent of item.extents) {
      if (extent.length === 0) continue;
      const start = addSafeOffsets(
        item.baseOffset,
        extent.offset,
        // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
        `Item ${item.id}'s surviving extent start`,
      );
      survivingRanges.push({
        start,
        end: addSafeOffsets(
          start,
          extent.length,
          // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
          `Item ${item.id}'s surviving extent end`,
        ),
        itemId: item.id,
      });
    }
  }
  for (const item of model.items) {
    if (kinds.get(item.id) !== "removable") continue;
    for (const extent of item.extents) {
      if (extent.length === 0) continue;
      const start = addSafeOffsets(
        item.baseOffset,
        extent.offset,
        // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
        `Item ${item.id}'s removable extent start`,
      );
      const end = addSafeOffsets(
        start,
        extent.length,
        // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
        `Item ${item.id}'s removable extent end`,
      );
      for (const surviving of survivingRanges) {
        if (start < surviving.end && surviving.start < end) {
          throw new IsobmffStructureError(
            "removable-extent-overlap",
            // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
            `Removable item ${item.id}'s extent [${start}, ${end}) overlaps surviving item ` +
              // Stryker disable next-line StringLiteral: unobservable-message — Offset context flows only through addSafeOffsets to StructureError message; numeric checks are unchanged.
              `${surviving.itemId}'s extent [${surviving.start}, ${surviving.end}).`,
          );
        }
      }
    }
  }

  const removableItemIds: number[] = [];
  const emptiedItemIds: number[] = [];
  const survivingItemIds: number[] = [];
  for (const item of model.items) {
    const kind = kinds.get(item.id);
    if (kind === "removable") {
      removableItemIds.push(item.id);
      if (
        item.extents.length === 0 ||
        item.extents.every((extent) => extent.length === 0)
      ) {
        emptiedItemIds.push(item.id);
      }
    } else if (kind === "surviving") {
      survivingItemIds.push(item.id);
    }
  }

  return {
    removableItemIds,
    emptiedItemIds,
    survivingItemIds,
    removableTopLevel: model.removableTopLevel,
  };
}

/**
 * Parse, classify, and read back the non-emptied removable items' own bytes (Exif/XMP), assembling
 * a `FormatAdmission`-shaped result (D-12). Every payload read is guarded by
 * `budget.consumeBuffered(length)` for that exact length, immediately before the matching
 * `readExactly` call (T-61-25) -- the only reads this function performs outside `meta`.
 */
export async function admitIsobmff(
  handle: FileHandle,
  size: number,
  signal?: AbortSignal,
  caps: IsobmffCaps = DEFAULT_ISOBMFF_CAPS,
): Promise<IsobmffAdmission> {
  const model = await parseIsobmff(handle, size, caps, signal);
  const classification = classifyIsobmffModel(model, size);

  const entries: MetadataEntry[] = [];
  const warnings: MetadataWarning[] = [];
  let orientation: OrientationState = { status: "absent" };
  let colorProfile: Buffer | undefined;
  const namespaces = new Set<IsobmffMetadataNamespace>();
  let resolutionNamespace: IsobmffMetadataNamespace | undefined;
  let sourceResolution: MinimalExifResolution | undefined;
  const exifSourceItemId = findExifSourceItemId(model, classification);

  if (model.colorProfile !== undefined) {
    colorProfile = model.colorProfile;
    namespaces.add("ICC");
    const found = parseIcc(colorProfile);
    entries.push(...found.entries);
    warnings.push(...found.warnings);
  }

  if (classification.removableTopLevel.length > 0) {
    namespaces.add("C2PA");
  }

  const budget = new IsobmffBudget(caps);
  const emptied = new Set(classification.emptiedItemIds);

  for (const itemId of classification.removableItemIds) {
    if (emptied.has(itemId)) continue;
    if (signal?.aborted === true) {
      throw new IsobmffStructureError("box-framing", "Parsing aborted.");
    }

    const item = model.itemsById.get(itemId);
    if (item === undefined) continue; // unreachable: classification is derived from model.items

    const parts: Buffer[] = [];
    for (const extent of item.extents) {
      const absoluteOffset = addSafeOffsets(
        item.baseOffset,
        extent.offset,
        `Item ${item.id}'s read extent start`,
      );
      budget.consumeBuffered(extent.length);
      parts.push(await readExactly(handle, extent.length, absoluteOffset));
    }
    const payload = Buffer.concat(parts);

    if (item.type === "Exif") {
      namespaces.add("EXIF");
      if (payload.length < 4) continue;
      // D-12: strip the 4-byte exif_tiff_header_offset prefix explicitly (the value names how
      // many further bytes of padding precede the TIFF header itself).
      const tiffHeaderOffset = payload.readUInt32BE(0);
      const tiff = payload.subarray(4 + tiffHeaderOffset);
      const found = parseExif(tiff);
      entries.push(...found.entries);
      warnings.push(...found.warnings);
      if (item.id === exifSourceItemId) {
        // D-13: orientation and resolution come only from source item k. An Exif item on an
        // auxiliary or thumbnail image (not k) still contributes its entries/warnings above (the
        // inspector keeps listing every removable item's metadata), but never its orientation or
        // resolution.
        orientation = found.orientation;
        const resolution = readIfd0Resolution(tiff);
        if (resolution !== undefined) {
          resolutionNamespace = "EXIF";
          sourceResolution = resolution;
        }
      }
      continue;
    }

    if (item.type === "mime") {
      namespaces.add("XMP");
      const found = parseXmp(payload);
      entries.push(...found.entries);
      warnings.push(...found.warnings);
      continue;
    }
  }

  return {
    entries,
    warnings,
    orientation,
    colorProfile,
    namespaces: Array.from(namespaces),
    resolutionNamespace,
    model,
    classification,
    exifSourceItemId,
    sourceResolution,
  };
}

tests/isobmff_writer.test.ts.source:
// Tracer (62-02): the thinnest real path through every layer Phase 62 touches -- parse layout ->
// output plan -> meta rebuild -> streaming writer -> identity verify -> engine-bound handler ->
// `sanitizeFile`, on the committed `heif-enc-grid.heic` fixture, removing its Exif and XMP items
// and proving the surviving items byte-identical. The handler stays unregistered throughout (D-02
// shape (c)): it is installed only through the private `setRegisteredHandlersForTests` seam.
import {
  copyFile,
  mkdtemp,
  open,
  readFile,
  readdir,
  rm,
  stat,
  writeFile,
} from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";
import { sanitizeFile } from "../src/engine.js";
import {
  registeredHandlersForTests,
  setRegisteredHandlersForTests,
} from "../src/admission/registry.js";
import { admitIsobmff } from "../src/isobmff/admission.js";
import {
  createIsobmffWriterHandlerForTests,
  createPlanMutantHandler,
  mutateIrefSquashSecondRecordFromK,
  mutateIpcoCorruptOrphanProperty,
} from "./isobmff-support/test-handler.js";
import {
  inventoryIsobmff,
  readItemExtentBytes,
  type InventoryItem,
  type IsobmffInventory,
} from "./isobmff-support/inventory.js";
import {
  auxC,
  av1C,
  box,
  ftypBox,
  grplBox,
  hdlrBox,
  hvcC,
  idatBox,
  iinfBox,
  ilocBox,
  infeBox,
  ipcoBox,
  ipmaBox,
  iprpBox,
  irefBox,
  ispe,
  mdatBox,
  metaBox,
  pitmBox,
  uuidBox,
  type BoxSizeOverride,
  type IlocItem,
  type IpmaEntry,
  type IrefRef,
} from "./isobmff-support/builder.js";
import {
  assembleHeif,
  HOSTILE_FIXTURES,
  type AssembleHeifSpec,
} from "./isobmff-support/hostile.js";
import { createMinimalExif } from "../src/metadata/exif.js";
import fc from "fast-check";
import {
  isobmffArmSampleArbitrary,
  type IsobmffArm,
} from "./isobmff-support/generator.js";

// C2PA's registered `uuid` usertype (d8fec3d6-1b0e-483c-9297-5828877ec481), restated here as a
// plain literal rather than imported -- `tests/isobmff-support/` files may only take a type-only
// import from `src/isobmff/`, and this file deliberately mirrors that same narrow discipline for
// anything it imports from `src/isobmff/*` directly (it does import `admitIsobmff` as a value,
// which is allowed outside `isobmff-support/`). Must stay equal to
// `src/isobmff/boxes.ts`'s `C2PA_UUID_USERTYPE`.
const C2PA_UUID_USERTYPE = "d8fec3d61b0e483c92975828877ec481";

const FIXTURES_DIR = join(
  dirname(fileURLToPath(import.meta.url)),
  "corpus",
  "constructed",
);
const HEIC_FIXTURE = join(FIXTURES_DIR, "heic", "heif-enc-grid.heic");
const AVIF_FIXTURE = join(FIXTURES_DIR, "avif", "heif-enc-grid.avif");

const directories: string[] = [];
afterEach(async () => {
  await Promise.all(
    directories
      .splice(0)
      .map((directory) => rm(directory, { recursive: true, force: true })),
  );
});

async function freshDirectory(): Promise<string> {
  const directory = await mkdtemp(
    join(tmpdir(), "exifcleaner-isobmff-writer-"),
  );
  directories.push(directory);
  return directory;
}

const SURVIVING_IMAGE_TYPES: ReadonlySet<string> = new Set(["grid", "hvc1"]);

function findItem(
  inventory: IsobmffInventory,
  id: number,
): InventoryItem | undefined {
  return inventory.items.find((item) => item.id === id);
}

describe("tracer: heif-enc-grid.heic rebuild (62-02)", () => {
  it("fails before the handler exists (recorded first run)", () => {
    // The first run of this test, before src/isobmff/{plan,rebuild,writer,verify}.ts and
    // src/admission/isobmff-handler.ts existed, failed at the `createIsobmffWriterHandlerForTests`
    // import with "Cannot find module '../src/admission/isobmff-handler.js'". Recorded per plan
    // instruction; this assertion itself is a no-op once the modules exist.
    expect(true).toBe(true);
  });

  it("rebuilds heif-enc-grid.heic end to end: removes Exif/XMP, preserves every surviving item byte-identical, leaks none of the removed payload, and re-admits", async () => {
    const directory = await freshDirectory();
    const sourceName = "source.heic";
    const destinationName = "destination.heic";
    const sourcePath = join(directory, sourceName);
    const destinationPath = join(directory, destinationName);
    await copyFile(HEIC_FIXTURE, sourcePath);
    const sourceBytesBefore = await readFile(sourcePath);

    const restore = setRegisteredHandlersForTests([
      createIsobmffWriterHandlerForTests("heic"),
    ]);
    try {
      const sanitized = await sanitizeFile({
        sourcePath,
        destinationPath,
        preserveOrientation: false,
        preserveColorProfile: true,
        preserveTimestamps: false,
        preserveResolution: false,
      });
      expect(sanitized.ok).toBe(true);
      if (!sanitized.ok) {
        throw new Error(
          `sanitizeFile failed: ${JSON.stringify(sanitized.error)}`,
        );
      }

      // Blast radius: the test directory lists exactly the source and the destination.
      const listing = await readdir(directory);
      expect(new Set(listing)).toEqual(new Set([sourceName, destinationName]));

      // The source is untouched.
      const sourceBytesAfter = await readFile(sourcePath);
      expect(sourceBytesAfter.equals(sourceBytesBefore)).toBe(true);

      const sourceInventory = inventoryIsobmff(sourceBytesBefore);
      const destinationBytes = await readFile(destinationPath);
      const destinationInventory = inventoryIsobmff(destinationBytes);

      const removedIds = new Set(
        sourceInventory.items
          .filter((item) => item.type === "Exif" || item.type === "mime")
          .map((item) => item.id),
      );
      expect(removedIds.size).toBe(2);

      // ISO-01: no Exif/mime item, no iloc entry, no ipma entry, no iref record whose from-item
      // is a removed item, for either removed ID.
      for (const item of destinationInventory.items) {
        expect(item.type).not.toBe("Exif");
        expect(item.type).not.toBe("mime");
        expect(removedIds.has(item.id)).toBe(false);
      }
      for (const association of destinationInventory.associations) {
        expect(removedIds.has(association.itemId)).toBe(false);
      }
      for (const reference of destinationInventory.references) {
        expect(removedIds.has(reference.from)).toBe(false);
        for (const toId of reference.to)
          expect(removedIds.has(toId)).toBe(false);
      }

      // ISO-03: every surviving item (the grid, its four tiles, and the thumbnail) has an output
      // payload byte-identical to its source payload, read through each file's own iloc/idat.
      const sourceSurviving = sourceInventory.items.filter((item) =>
        SURVIVING_IMAGE_TYPES.has(item.type),
      );
      expect(sourceSurviving.map((item) => item.id)).toEqual([
        1, 2, 3, 4, 5, 8,
      ]);
      const destinationSurviving = destinationInventory.items.filter((item) =>
        SURVIVING_IMAGE_TYPES.has(item.type),
      );
      expect(destinationSurviving.map((item) => item.id)).toEqual(
        sourceSurviving.map((item) => item.id),
      );
      for (const sourceItem of sourceSurviving) {
        const destinationItem = findItem(destinationInventory, sourceItem.id);
        expect(destinationItem).toBeDefined();
        const sourcePayload = readItemExtentBytes(
          sourceBytesBefore,
          sourceInventory,
          sourceItem,
        );
        const destinationPayload = readItemExtentBytes(
          destinationBytes,
          destinationInventory,
          destinationItem!,
        );
        expect(destinationPayload.equals(sourcePayload)).toBe(true);
      }

      // The output re-admits through admitIsobmff.
      const destinationHandle: FileHandle = await open(destinationPath, "r");
      try {
        const reAdmitted = await admitIsobmff(
          destinationHandle,
          destinationBytes.length,
        );
        expect(reAdmitted.namespaces).not.toContain("EXIF");
        expect(reAdmitted.namespaces).not.toContain("XMP");
      } finally {
        await destinationHandle.close();
      }

      // Blast radius: neither removed item's source payload bytes occur anywhere in the output.
      for (const item of sourceInventory.items) {
        if (item.type !== "Exif" && item.type !== "mime") continue;
        const removedPayload = readItemExtentBytes(
          sourceBytesBefore,
          sourceInventory,
          item,
        );
        expect(removedPayload.length).toBeGreaterThan(0);
        expect(destinationBytes.indexOf(removedPayload)).toBe(-1);
      }
    } finally {
      restore();
    }
  });
});

describe("Task 2: the writer handlers' registration and brand separation (62-02, registered in 62.1-07)", () => {
  it("registeredHandlersForTests() returns exactly the webp, png, jpeg, heic and avif handlers (62.1-07 D-03/D-08)", () => {
    expect(
      registeredHandlersForTests().map((h) => h.capability.format),
    ).toEqual(["webp", "png", "jpeg", "heic", "avif"]);
  });

  it("the AVIF fixture does not match the heic writer handler and the HEIC fixture does not match the avif writer handler", async () => {
    const heicWriterHandler = createIsobmffWriterHandlerForTests("heic");
    const avifWriterHandler = createIsobmffWriterHandlerForTests("avif");

    const heicMagic = (await readFile(HEIC_FIXTURE)).subarray(0, 256);
    const avifMagic = (await readFile(AVIF_FIXTURE)).subarray(0, 256);

    expect(heicWriterHandler.matches(heicMagic)).toBe(true);
    expect(heicWriterHandler.matches(avifMagic)).toBe(false);
    expect(avifWriterHandler.matches(avifMagic)).toBe(true);
    expect(avifWriterHandler.matches(heicMagic)).toBe(false);
  });
});

// --- Task 2 (62-05): the D-11 iloc layout matrix ---
//
// A bespoke byte-level fixture builder (not `assembleHeif`, which hardcodes iloc version 1) --
// one removable Exif item (cm=0, 1 extent) before a surviving multi-extent primary (cm=0, 2
// extents, declared in ascending-source-offset order) and, for every version that has a
// construction_method field (v1/v2), a surviving grid item (cm=1, 1 extent into idat) to prove
// construction_method-1 records and their idat payload stay verbatim. `mdatPayload` deliberately
// carries a 6-byte unclaimed gap between the primary's two extents so this fixture also doubles
// as a basic D-15 "unclaimed gap dropped" proof once Task 3's canary tests land.

const MATRIX_EXIF_ID = 1;
const MATRIX_PRIMARY_ID = 2;
const MATRIX_GRID_ID = 3;

interface LayoutMatrixCase {
  readonly version: 0 | 1 | 2;
  readonly offsetSize: 4 | 8;
  readonly lengthSize: 4 | 8;
  readonly baseOffsetSize: 0 | 4 | 8;
  readonly indexSize: 0 | 4 | 8;
}

/** D-11: the base/offset encoding for one cm=0 item's extents, given where they land absolutely
 * in the source file and the declared `baseOffsetSize`. */
function cm0IlocFields(
  absExtents: readonly {
    readonly abs: number;
    readonly length: number;
    readonly index: number;
  }[],
  baseOffsetSize: 0 | 4 | 8,
): { readonly baseOffset: number; readonly extents: IlocItem["extents"] } {
  if (baseOffsetSize > 0) {
    const base = absExtents[0]!.abs;
    return {
      baseOffset: base,
      extents: absExtents.map((e) => ({
        offset: e.abs - base,
        length: e.length,
        index: e.index,
      })),
    };
  }
  return {
    baseOffset: 0,
    extents: absExtents.map((e) => ({
      offset: e.abs,
      length: e.length,
      index: e.index,
    })),
  };
}

function buildLayoutMatrixFixture(c: LayoutMatrixCase): {
  readonly bytes: Buffer;
  readonly removedItemId: number;
  readonly survivingPrimaryId: number;
  readonly survivingGridId: number | undefined;
} {
  const hasCm = c.version !== 0;
  const mdatPayload = Buffer.concat([
    Buffer.from([0x10, 0x11, 0x12, 0x13]), // primary extent 0: [0, 4)
    Buffer.from([0, 0, 0, 0, 0, 0]), // unclaimed gap: [4, 10)
    Buffer.from([0x20, 0x21, 0x22, 0x23, 0x24, 0x25]), // primary extent 1: [10, 16)
    Buffer.from([0x30, 0x31, 0x32, 0x33]), // exif (removable): [16, 20)
  ]);
  const idatPayload = hasCm
    ? Buffer.from([0x40, 0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49])
    : undefined;

  const build = (mdatPayloadStart: number): Buffer => {
    const ftyp = ftypBox("heic", 0, ["mif1", "heic"]);
    const hdlr = hdlrBox("pict");
    const pitm = pitmBox(0, MATRIX_PRIMARY_ID);

    const infeEntries = [
      infeBox({
        version: 2,
        itemId: MATRIX_EXIF_ID,
        itemType: "Exif",
        hidden: true,
      }),
      infeBox({ version: 2, itemId: MATRIX_PRIMARY_ID, itemType: "hvc1" }),
    ];
    if (hasCm) {
      infeEntries.push(
        infeBox({ version: 2, itemId: MATRIX_GRID_ID, itemType: "grid" }),
      );
    }
    const iinf = iinfBox(0, infeEntries);

    const ipco = ipcoBox([ispe(32, 32), hvcC()]);
    const ipmaEntries: IpmaEntry[] = [
      {
        itemId: MATRIX_PRIMARY_ID,
        associations: [
          { propertyIndex: 1, essential: false },
          { propertyIndex: 2, essential: false },
        ],
      },
    ];
    if (hasCm) {
      ipmaEntries.push({
        itemId: MATRIX_GRID_ID,
        associations: [{ propertyIndex: 1, essential: false }],
      });
    }
    const ipma = ipmaBox({ version: 0, flags: 0, entries: ipmaEntries });
    const iprp = iprpBox(ipco, ipma);
    const idat = idatPayload !== undefined ? idatBox(idatPayload) : undefined;

    const exifFields = cm0IlocFields(
      [{ abs: mdatPayloadStart + 16, length: 4, index: 3 }],
      c.baseOffsetSize,
    );
    const primaryFields = cm0IlocFields(
      [
        { abs: mdatPayloadStart + 0, length: 4, index: 7 },
        { abs: mdatPayloadStart + 10, length: 6, index: 9 },
      ],
      c.baseOffsetSize,
    );

    const ilocItems: IlocItem[] = [
      {
        itemId: MATRIX_EXIF_ID,
        constructionMethod: 0,
        dataReferenceIndex: 0,
        baseOffset: exifFields.baseOffset,
        extents: exifFields.extents,
      },
      {
        itemId: MATRIX_PRIMARY_ID,
        constructionMethod: 0,
        dataReferenceIndex: 0,
        baseOffset: primaryFields.baseOffset,
        extents: primaryFields.extents,
      },
    ];
    if (hasCm) {
      ilocItems.push({
        itemId: MATRIX_GRID_ID,
        constructionMethod: 1,
        dataReferenceIndex: 0,
        baseOffset: 0,
        extents: [{ offset: 0, length: idatPayload!.length, index: 5 }],
      });
    }

    const iloc = ilocBox({
      version: c.version,
      offsetSize: c.offsetSize,
      lengthSize: c.lengthSize,
      baseOffsetSize: c.baseOffsetSize,
      indexSize: c.indexSize,
      items: ilocItems,
    });

    const metaChildren: Buffer[] = [hdlr, pitm];
    if (idat !== undefined) metaChildren.push(idat);
    metaChildren.push(iloc, iinf, iprp);
    const meta = metaBox(metaChildren);
    const header = Buffer.concat([ftyp, meta]);
    return Buffer.concat([header, mdatBox(mdatPayload)]);
  };

  const pass1 = build(0);
  const mdatBoxTotal = 8 + mdatPayload.length;
  const headerLength = pass1.length - mdatBoxTotal;
  const final = build(headerLength + 8);
  if (final.length !== pass1.length) {
    throw new Error(
      "buildLayoutMatrixFixture: header length changed between placeholder and final passes",
    );
  }

  return {
    bytes: final,
    removedItemId: MATRIX_EXIF_ID,
    survivingPrimaryId: MATRIX_PRIMARY_ID,
    survivingGridId: hasCm ? MATRIX_GRID_ID : undefined,
  };
}

/** Explicit table (D-11): every admitted version x width combination this build supports, never
 * random sampling. `offset_size` is never 0 for a surviving item (D-31). */
const LAYOUT_MATRIX: readonly LayoutMatrixCase[] = (() => {
  const cases: LayoutMatrixCase[] = [];
  const baseOffsetSizes: readonly (0 | 4 | 8)[] = [0, 4, 8];
  for (const baseOffsetSize of baseOffsetSizes) {
    cases.push({
      version: 0,
      offsetSize: 4,
      lengthSize: 4,
      baseOffsetSize,
      indexSize: 0,
    });
    cases.push({
      version: 0,
      offsetSize: 8,
      lengthSize: 4,
      baseOffsetSize,
      indexSize: 0,
    });
    for (const indexSize of [0, 4, 8] as const) {
      cases.push({
        version: 1,
        offsetSize: 4,
        lengthSize: 4,
        baseOffsetSize,
        indexSize,
      });
      cases.push({
        version: 2,
        offsetSize: 4,
        lengthSize: 4,
        baseOffsetSize,
        indexSize,
      });
    }
  }
  // A couple of explicit lengthSize/offsetSize=8 combinations, so those widths are exercised too.
  cases.push({
    version: 1,
    offsetSize: 4,
    lengthSize: 8,
    baseOffsetSize: 4,
    indexSize: 4,
  });
  cases.push({
    version: 2,
    offsetSize: 8,
    lengthSize: 8,
    baseOffsetSize: 8,
    indexSize: 8,
  });
  return cases;
})();

function titleForMatrixCase(c: LayoutMatrixCase): string {
  return (
    `v${c.version} offsetSize=${c.offsetSize} lengthSize=${c.lengthSize} ` +
    `baseOffsetSize=${c.baseOffsetSize} indexSize=${c.indexSize}`
  );
}

describe("D-11 iloc layout matrix (62-05)", () => {
  it.each(LAYOUT_MATRIX.map((c) => [titleForMatrixCase(c), c] as const))(
    "%s",
    async (_title, c) => {
      const { bytes, removedItemId, survivingPrimaryId, survivingGridId } =
        buildLayoutMatrixFixture(c);
      const directory = await freshDirectory();
      const sourcePath = join(directory, "source.heic");
      const destinationPath = join(directory, "destination.heic");
      await writeFile(sourcePath, bytes);

      const restore = setRegisteredHandlersForTests([
        createIsobmffWriterHandlerForTests("heic"),
      ]);
      try {
        const sanitized = await sanitizeFile({
          sourcePath,
          destinationPath,
          preserveOrientation: false,
          preserveColorProfile: false,
          preserveTimestamps: false,
          preserveResolution: false,
        });
        expect(sanitized.ok).toBe(true);
        if (!sanitized.ok) {
          throw new Error(
            `sanitizeFile failed: ${JSON.stringify(sanitized.error)}`,
          );
        }

        const destinationBytes = await readFile(destinationPath);
        const sourceInventory = inventoryIsobmff(bytes);
        const destinationInventory = inventoryIsobmff(destinationBytes);

        // Source version and all four widths unchanged.
        expect(destinationInventory.iloc).toEqual(sourceInventory.iloc);

        // The removed item is gone entirely.
        expect(
          destinationInventory.items.some((item) => item.id === removedItemId),
        ).toBe(false);

        const survivingIds = [
          survivingPrimaryId,
          ...(survivingGridId !== undefined ? [survivingGridId] : []),
        ];
        for (const id of survivingIds) {
          const sourceItem = findItem(sourceInventory, id);
          const destinationItem = findItem(destinationInventory, id);
          expect(sourceItem).toBeDefined();
          expect(destinationItem).toBeDefined();

          // Every surviving item's payload is byte-identical, read through each file's own iloc.
          const sourcePayload = readItemExtentBytes(
            bytes,
            sourceInventory,
            sourceItem!,
          );
          const destinationPayload = readItemExtentBytes(
            destinationBytes,
            destinationInventory,
            destinationItem!,
          );
          expect(destinationPayload.equals(sourcePayload)).toBe(true);

          // extent_index copied verbatim (D-11), including the grid's cm=1 record.
          expect(destinationItem!.extents.map((e) => e.index)).toEqual(
            sourceItem!.extents.map((e) => e.index),
          );
          expect(destinationItem!.constructionMethod).toBe(
            sourceItem!.constructionMethod,
          );
        }

        // D-11 base/offset formulas for the surviving cm=0 primary. The source's 6-byte
        // unclaimed gap between the primary's two extents (D-15) is dropped from the new mdat
        // payload, so the two extents land only 4 bytes apart in the output -- never the
        // source's own 10-byte separation.
        const destinationPrimary = findItem(
          destinationInventory,
          survivingPrimaryId,
        )!;
        if (c.baseOffsetSize > 0) {
          expect(destinationPrimary.extents[0]!.offset).toBe(0);
          expect(destinationPrimary.extents[1]!.offset).toBe(4);
        } else {
          expect(destinationPrimary.baseOffset).toBe(0);
          expect(destinationPrimary.extents[1]!.offset).toBe(
            destinationPrimary.extents[0]!.offset + 4,
          );
        }
      } finally {
        restore();
      }
    },
  );

  it("has at least 18 cases, including base_offset_size 0 and base_offset_size 8", () => {
    expect(LAYOUT_MATRIX.length).toBeGreaterThanOrEqual(18);
    expect(LAYOUT_MATRIX.some((c) => c.baseOffsetSize === 0)).toBe(true);
    expect(LAYOUT_MATRIX.some((c) => c.baseOffsetSize === 8)).toBe(true);
  });
});

// --- Task 3 (62-05): D-15 mdat union, gaps, header forms and adjacency ---

async function runThroughWriter(bytes: Buffer): Promise<{
  readonly sourcePath: string;
  readonly destinationBytes: Buffer;
  readonly sourceInventory: IsobmffInventory;
  readonly destinationInventory: IsobmffInventory;
}> {
  const directory = await freshDirectory();
  const sourcePath = join(directory, "source.heic");
  const destinationPath = join(directory, "destination.heic");
  await writeFile(sourcePath, bytes);

  const restore = setRegisteredHandlersForTests([
    createIsobmffWriterHandlerForTests("heic"),
  ]);
  try {
    const sanitized = await sanitizeFile({
      sourcePath,
      destinationPath,
      preserveOrientation: false,
      preserveColorProfile: false,
      preserveTimestamps: false,
      preserveResolution: false,
    });
    if (!sanitized.ok) {
      throw new Error(
        `sanitizeFile failed: ${JSON.stringify(sanitized.error)}`,
      );
    }
    expect(sanitized.ok).toBe(true);
    const destinationBytes = await readFile(destinationPath);
    return {
      sourcePath,
      destinationBytes,
      sourceInventory: inventoryIsobmff(bytes),
      destinationInventory: inventoryIsobmff(destinationBytes),
    };
  } finally {
    restore();
  }
}

/** A bespoke single-item fixture (not `assembleHeif`, which never exposes an `mdat` size
 * override) isolating the `mdat` header form: one surviving `hvc1` item occupies the whole
 * payload, cm=0, widths 4/4/4/0. */
function buildMdatFormFixture(
  mdatSizeOverride: BoxSizeOverride["size"],
  payload: Buffer,
): Buffer {
  const headerSize = mdatSizeOverride === "largesize" ? 16 : 8;
  const itemId = 1;

  const build = (mdatPayloadStart: number): Buffer => {
    const ftyp = ftypBox("heic", 0, ["mif1", "heic"]);
    const hdlr = hdlrBox("pict");
    const pitm = pitmBox(0, itemId);
    const infe = infeBox({ version: 2, itemId, itemType: "hvc1" });
    const iinf = iinfBox(0, [infe]);
    const ipco = ipcoBox([ispe(32, 32), hvcC()]);
    const ipma = ipmaBox({
      version: 0,
      flags: 0,
      entries: [
        { itemId, associations: [{ propertyIndex: 1, essential: false }] },
      ],
    });
    const iprp = iprpBox(ipco, ipma);
    const iloc = ilocBox({
      version: 1,
      offsetSize: 4,
      lengthSize: 4,
      baseOffsetSize: 4,
      indexSize: 0,
      items: [
        {
          itemId,
          constructionMethod: 0,
          dataReferenceIndex: 0,
          baseOffset: mdatPayloadStart,
          extents: [{ offset: 0, length: payload.length, index: 0 }],
        },
      ],
    });
    const meta = metaBox([hdlr, pitm, iloc, iinf, iprp]);
    const header = Buffer.concat([ftyp, meta]);
    const mdat = mdatBox(
      payload,
      mdatSizeOverride !== undefined ? { size: mdatSizeOverride } : {},
    );
    return Buffer.concat([header, mdat]);
  };

  const pass1 = build(0);
  const mdatTotal = headerSize + payload.length;
  const headerLength = pass1.length - mdatTotal;
  const final = build(headerLength + headerSize);
  if (final.length !== pass1.length) {
    throw new Error(
      "buildMdatFormFixture: header length changed between placeholder and final passes",
    );
  }
  return final;
}

