          propertyIndices: [1, 2],
        },
      ],
      mdatPayload: Buffer.from([1, 2, 3, 4]),
      topLevelExtraAfterFtyp: [
        uuidBox(C2PA_UUID_USERTYPE, Buffer.alloc(16, 0x11)),
      ],
      topLevelExtraAfterMdat: [
        uuidBox(C2PA_UUID_USERTYPE, Buffer.alloc(16, 0x22)),
