// 62-07, Task 2: item shape, placement variants, empty cases. All builder fixtures, isolated from
// the committed heif-enc fixtures Task 1 already proved end to end.
describe("D-13 minimal Exif writer item shape and placement variants (62-07)", () => {
  const PRIMARY_PAYLOAD = Buffer.from("primary-bytes", "ascii");

  /** A single surviving primary (`hvc1`, item 1) plus one Exif item (item 2, k, `cdsc` -> the
   * primary and optionally extra targets) carrying `exifTiff`. `twoPass` resolves real absolute
   * offsets, needed because the writer's own D-11 placement math depends on them. */
  function buildSingleExifFixture(options: {
    readonly exifTiff: Buffer;
    readonly infeVersion?: 0 | 1 | 2 | 3;
    readonly hidden?: boolean;
    readonly baseOffsetSize?: 0 | 4 | 8;
  }): Buffer {
    const exifPayload = Buffer.concat([Buffer.alloc(4), options.exifTiff]);
    return assembleHeif({
      primaryItemId: 1,
      items: [
        {
          itemId: 1,
          itemType: "hvc1",
          extents: [{ relOffset: 0, length: PRIMARY_PAYLOAD.length }],
        },
        {
          itemId: 2,
          itemType: "Exif",
          hidden: options.hidden ?? true,
          ...(options.infeVersion !== undefined
            ? { infeVersion: options.infeVersion }
            : {}),
          extents: [
            { relOffset: PRIMARY_PAYLOAD.length, length: exifPayload.length },
          ],
        },
      ],
      refs: [{ type: "cdsc", fromItemId: 2, toItemIds: [1] }],
      mdatPayload: Buffer.concat([PRIMARY_PAYLOAD, exifPayload]),
      ilocWidths: {
        offsetSize: 4,
        lengthSize: 4,
        baseOffsetSize: options.baseOffsetSize ?? 4,
      },
      twoPass: true,
    });
  }

  async function sanitize(
    bytes: Buffer,
    overrides: Partial<Parameters<typeof sanitizeFile>[0]> = {},
  ): Promise<{
    readonly destinationPath: string;
    readonly destinationBytes: Buffer;
  }> {
    const { path: sourcePath } = await writeFixture(bytes);
    const directory = dirname(sourcePath);
    const destinationPath = join(directory, "destination.heic");
    const restore = setRegisteredHandlersForTests([
      createIsobmffWriterHandlerForTests("heic"),
    ]);
    try {
      const sanitized = await sanitizeFile({
        sourcePath,
        destinationPath,
        preserveOrientation: true,
        preserveColorProfile: true,
        preserveTimestamps: false,
        preserveResolution: true,
        ...overrides,
      });
      expect(sanitized.ok).toBe(true);
      if (!sanitized.ok) {
        throw new Error(
          `sanitizeFile failed: ${JSON.stringify(sanitized.error)}`,
        );
      }
      const destinationBytes = await readFile(destinationPath);
      return { destinationPath, destinationBytes };
    } finally {
      restore();
    }
  }

  it.each([[2, false] as const, [3, true] as const])(
    "infe version %i, hidden %s: the output infe keeps that version and flag, with an empty name and item_protection_index 0",
    async (version, hidden) => {
      const bytes = buildSingleExifFixture({
        exifTiff: createOrientationExif(6),
        infeVersion: version,
        hidden,
      });
      const { destinationBytes } = await sanitize(bytes);

      const expectedInfe = buildMinimalExifInfe(version, hidden, 2);
      expect(destinationBytes.includes(expectedInfe)).toBe(true);

      const inventory = inventoryIsobmff(destinationBytes);
      const exifItem = inventory.items.find((item) => item.id === 2);
      expect(exifItem).toBeDefined();
      expect(exifItem!.hidden).toBe(hidden);
    },
  );

  /**
   * `assembleHeif`'s generic `twoPass` helper always writes a cm=0 item's absolute position as
   * `baseOffset (= mdatPayloadStart) + relOffset` -- correct only when `baseOffsetSize > 0` (the
   * base field actually carries `mdatPayloadStart`). With `baseOffsetSize === 0` the base field
   * is never written at all (0 implied), so the raw `extent.offset` itself must already BE the
   * absolute position -- a shape the generic helper cannot produce (it has no way to learn
   * `mdatPayloadStart` before computing `relOffset`). This bespoke two-pass builder (same pattern
   * as `isobmff_hostile.test.ts`'s `buildWithExtraIprpChild`) sets the real absolute offset
   * directly, mirroring a real `base_offset_size 0` writer (e.g. old cavif/libavif, D-31).
   */
  function buildBaseOffsetZeroFixture(exifTiff: Buffer): Buffer {
    const exifPayload = Buffer.concat([Buffer.alloc(4), exifTiff]);
    const mdatPayload = Buffer.concat([PRIMARY_PAYLOAD, exifPayload]);
    const build = (mdatPayloadStart: number): Buffer => {
      const ftyp = ftypBox("heic", 0, ["mif1", "heic"]);
      const hdlr = hdlrBox("pict");
      const pitm = pitmBox(0, 1);
      const infe1 = infeBox({ version: 2, itemId: 1, itemType: "hvc1" });
      const infe2 = infeBox({
        version: 2,
        itemId: 2,
        itemType: "Exif",
        hidden: true,
      });
      const iinf = iinfBox(0, [infe1, infe2]);
      const ipco = ipcoBox([ispe(32, 32), hvcC()]);
      const ipma = ipmaBox({
        version: 0,
        flags: 0,
        entries: [
          {
            itemId: 1,
            associations: [
              { propertyIndex: 1, essential: false },
              { propertyIndex: 2, essential: true },
            ],
          },
        ],
      });
      const iprp = iprpBox(ipco, ipma);
      const iloc = ilocBox({
        version: 1,
        offsetSize: 4,
        lengthSize: 4,
        baseOffsetSize: 0,
        indexSize: 0,
        items: [
          {
            itemId: 1,
            constructionMethod: 0,
            dataReferenceIndex: 0,
            baseOffset: 0,
            extents: [
              { offset: mdatPayloadStart, length: PRIMARY_PAYLOAD.length },
            ],
          },
          {
            itemId: 2,
            constructionMethod: 0,
            dataReferenceIndex: 0,
            baseOffset: 0,
            extents: [
              {
                offset: mdatPayloadStart + PRIMARY_PAYLOAD.length,
                length: exifPayload.length,
              },
            ],
          },
        ],
      });
      const iref = irefBox(0, [
        { type: "cdsc", fromItemId: 2, toItemIds: [1] },
      ]);
      const meta = metaBox([hdlr, pitm, iinf, iloc, iprp, iref]);
      const header = Buffer.concat([ftyp, meta]);
      const mdat = mdatBox(mdatPayload);
      return Buffer.concat([header, mdat]);
    };
    const pass1 = build(0);
    const mdatBoxTotal = 8 + mdatPayload.length;
    const headerLength = pass1.length - mdatBoxTotal;
    const final = build(headerLength + 8);
    if (final.length !== pass1.length) {
      throw new Error(
        "buildBaseOffsetZeroFixture: header length changed between placeholder and final passes",
      );
    }
    return final;
  }

  it("base_offset_size 0: the extent offset carries the tail position, with no base field", async () => {
    const bytes = buildBaseOffsetZeroFixture(createOrientationExif(6));
    const { destinationBytes } = await sanitize(bytes);
    const inventory = inventoryIsobmff(destinationBytes);
    const exifItem = inventory.items.find((item) => item.id === 2)!;
    const mdatBox = inventory.topLevel.find((box) => box.type === "mdat")!;
    const expectedTail = mdatBox.offset + 8 + PRIMARY_PAYLOAD.length;

    expect(exifItem.baseOffset).toBe(0);
    expect(exifItem.extents).toHaveLength(1);
    expect(exifItem.extents[0]!.offset).toBe(expectedTail);
  });

  it("base_offset_size 4: the base carries the tail position, with extent offset 0", async () => {
    const bytes = buildSingleExifFixture({
      exifTiff: createOrientationExif(6),
      baseOffsetSize: 4,
    });
    const { destinationBytes } = await sanitize(bytes);
    const inventory = inventoryIsobmff(destinationBytes);
    const exifItem = inventory.items.find((item) => item.id === 2)!;
    const mdatBox = inventory.topLevel.find((box) => box.type === "mdat")!;
    const expectedTail = mdatBox.offset + 8 + PRIMARY_PAYLOAD.length;

    expect(exifItem.baseOffset).toBe(expectedTail);
    expect(exifItem.extents).toHaveLength(1);
    expect(exifItem.extents[0]!.offset).toBe(0);
  });

  it(
    "adjacency: the minimal Exif payload starts exactly where the surviving union ends, and the " +
      "mdat payload length equals the union plus the payload length",
    async () => {
      const bytes = buildSingleExifFixture({
        exifTiff: createOrientationExif(6),
      });
      const { destinationBytes } = await sanitize(bytes);
      const inventory = inventoryIsobmff(destinationBytes);
      const exifItem = inventory.items.find((item) => item.id === 2)!;
      const mdatBox = inventory.topLevel.find((box) => box.type === "mdat")!;
      const expectedPayload = Buffer.concat([
        Buffer.alloc(4),
        createOrientationExif(6),
      ]);

      const exifAbsoluteStart =
        exifItem.baseOffset + exifItem.extents[0]!.offset;
      expect(exifAbsoluteStart).toBe(
        mdatBox.offset + 8 + PRIMARY_PAYLOAD.length,
      );
      expect(mdatBox.size).toBe(
        8 + PRIMARY_PAYLOAD.length + expectedPayload.length,
      );
    },
  );

  it("k's cdsc to-list [pitm, thumbnail] in the source reduces to [pitm] in the output, same slot", async () => {
    const thumbPayload = Buffer.from("thumb-bytes", "ascii");
    const exifTiff = createOrientationExif(6);
    const exifPayload = Buffer.concat([Buffer.alloc(4), exifTiff]);
    const bytes = assembleHeif({
      primaryItemId: 1,
      items: [
        {
          itemId: 1,
          itemType: "hvc1",
          extents: [{ relOffset: 0, length: PRIMARY_PAYLOAD.length }],
        },
        {
          itemId: 3,
          itemType: "hvc1",
          extents: [
            { relOffset: PRIMARY_PAYLOAD.length, length: thumbPayload.length },
          ],
        },
        {
          itemId: 2,
          itemType: "Exif",
          hidden: true,
          extents: [
            {
              relOffset: PRIMARY_PAYLOAD.length + thumbPayload.length,
              length: exifPayload.length,
            },
          ],
        },
      ],
      refs: [
        { type: "thmb", fromItemId: 3, toItemIds: [1] },
        { type: "cdsc", fromItemId: 2, toItemIds: [1, 3] },
      ],
      mdatPayload: Buffer.concat([PRIMARY_PAYLOAD, thumbPayload, exifPayload]),
      twoPass: true,
    });
    const { destinationBytes } = await sanitize(bytes);
    const inventory = inventoryIsobmff(destinationBytes);
    const cdscRecords = inventory.references.filter(
      (ref) => ref.type === "cdsc",
    );
    expect(cdscRecords).toEqual([{ type: "cdsc", from: 2, to: [1] }]);
    // Same slot: the record order matches the source's (thmb from item 3, then cdsc from k) --
    // only the cdsc record's to-list is reduced, its position in iref is untouched.
    expect(inventory.references).toEqual([
      { type: "thmb", from: 3, to: [1] },
      { type: "cdsc", from: 2, to: [1] },
    ]);
  });

  it("orientation only (resolution flag false) writes a payload with only the Orientation tag", async () => {
    const bytes = buildSingleExifFixture({
      exifTiff: createMinimalExif({
        orientation: 3,
        resolution: resolutionOf(200, 100),
      }),
    });
    const { destinationBytes } = await sanitize(bytes, {
      preserveOrientation: true,
      preserveResolution: false,
    });
    const inventory = inventoryIsobmff(destinationBytes);
    const exifItem = inventory.items.find((item) => item.id === 2)!;
    const payload = readItemExtentBytes(destinationBytes, inventory, exifItem);
    expect(
      payload.equals(
        Buffer.concat([Buffer.alloc(4), createMinimalExif({ orientation: 3 })]),
      ),
    ).toBe(true);
  });

  it("resolution only (orientation flag false) writes a payload with only the resolution tags", async () => {
    const bytes = buildSingleExifFixture({
      exifTiff: createMinimalExif({
        orientation: 3,
        resolution: resolutionOf(200, 100),
      }),
    });
    const { destinationBytes } = await sanitize(bytes, {
      preserveOrientation: false,
      preserveResolution: true,
    });
    const inventory = inventoryIsobmff(destinationBytes);
    const exifItem = inventory.items.find((item) => item.id === 2)!;
    const payload = readItemExtentBytes(destinationBytes, inventory, exifItem);
    expect(
      payload.equals(
        Buffer.concat([
          Buffer.alloc(4),
          createMinimalExif({ resolution: resolutionOf(200, 100) }),
        ]),
      ),
    ).toBe(true);
  });

  it("preserve flags false: no Exif item in the output", async () => {
    const bytes = buildSingleExifFixture({
      exifTiff: createOrientationExif(6),
    });
    const { destinationBytes } = await sanitize(bytes, {
      preserveOrientation: false,
      preserveResolution: false,
    });
    const inventory = inventoryIsobmff(destinationBytes);
    expect(inventory.items.some((item) => item.type === "Exif")).toBe(false);
  });

  it("k absent (thumbnail-only Exif): no Exif item in the output", async () => {
    const thumbPayload = Buffer.from("thumb-bytes", "ascii");
    const exifTiff = createOrientationExif(6);
    const exifPayload = Buffer.concat([Buffer.alloc(4), exifTiff]);
    const bytes = assembleHeif({
      primaryItemId: 1,
      items: [
        {
          itemId: 1,
          itemType: "hvc1",
          extents: [{ relOffset: 0, length: PRIMARY_PAYLOAD.length }],
        },
        {
          itemId: 3,
          itemType: "hvc1",
          extents: [
            { relOffset: PRIMARY_PAYLOAD.length, length: thumbPayload.length },
          ],
        },
        {
          itemId: 2,
          itemType: "Exif",
          hidden: true,
          extents: [
            {
              relOffset: PRIMARY_PAYLOAD.length + thumbPayload.length,
              length: exifPayload.length,
            },
          ],
        },
      ],
      refs: [
        { type: "thmb", fromItemId: 3, toItemIds: [1] },
        { type: "cdsc", fromItemId: 2, toItemIds: [3] },
      ],
      mdatPayload: Buffer.concat([PRIMARY_PAYLOAD, thumbPayload, exifPayload]),
      twoPass: true,
    });
    const { destinationBytes } = await sanitize(bytes);
    const inventory = inventoryIsobmff(destinationBytes);
    expect(inventory.items.some((item) => item.type === "Exif")).toBe(false);
  });

  it("k with neither tag (empty IFD0): no Exif item in the output", async () => {
    const emptyIfd0 = Buffer.alloc(14);
    emptyIfd0.write("II", 0, "ascii");
    emptyIfd0.writeUInt16LE(42, 2);
    emptyIfd0.writeUInt32LE(8, 4);
    emptyIfd0.writeUInt16LE(0, 8);
    emptyIfd0.writeUInt32LE(0, 10);

    const bytes = buildSingleExifFixture({ exifTiff: emptyIfd0 });
    const { destinationBytes } = await sanitize(bytes);
    const inventory = inventoryIsobmff(destinationBytes);
    expect(inventory.items.some((item) => item.type === "Exif")).toBe(false);
  });

  // The "heif-enc-grid.avif default settings" bullet is already proven by the Task 1 "D-13
  // minimal Exif writer (62-07)" describe block's `it.each` avif case above -- not duplicated here.
});

tests/isobmff_admission.test.ts.source:
// src/isobmff/admission.ts coverage (BMF-04): the D3/D5 admission classifier over the validated
// item graph (61-07), proven on both real `heif-enc` fixtures, a hand-built measured-iPhone-shaped
// file, and every D-10a empty/adjacency/direction edge from the amended plan.
import { mkdtemp, open, rm } from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";
import {
  admitIsobmff,
  classifyIsobmffModel,
  DECLINE_RULE_ORDER,
  PRESERVED_ITEM_TYPES,
  XMP_CONTENT_TYPES,
} from "../src/isobmff/admission.js";
import { C2PA_UUID_USERTYPE } from "../src/isobmff/boxes.js";
import { IsobmffStructureError } from "../src/isobmff/errors.js";
import { parseIsobmff } from "../src/isobmff/parse.js";
import { createOrientationExif } from "../src/metadata/exif.js";
import { heicHandler } from "../src/admission/heic-handler.js";
import { avifHandler } from "../src/admission/avif-handler.js";
import {
  auxC,
  colrProf,
  ftypBox,
  grplBox,
  hdlrBox,
  idatBox,
  iinfBox,
  ilocBox,
  infeBox,
  ipcoBox,
  ipmaBox,
  iprpBox,
  irefBox,
  mdatBox,
  metaBox,
  pitmBox,
  uuidBox,
  type GrplGroup,
  type IrefRef,
} from "./isobmff-support/builder.js";

const FIXTURES_DIR = join(
  dirname(fileURLToPath(import.meta.url)),
  "corpus",
  "constructed",
);
const HEIC_PATH = join(FIXTURES_DIR, "heic", "heif-enc-grid.heic");
const AVIF_PATH = join(FIXTURES_DIR, "avif", "heif-enc-grid.avif");

const cleanupDirectories: string[] = [];

afterEach(async () => {
  while (cleanupDirectories.length > 0) {
    const directory = cleanupDirectories.pop();
    if (directory !== undefined) {
      await rm(directory, { recursive: true, force: true });
    }
  }
});

async function freshDirectory(): Promise<string> {
  const directory = await mkdtemp(
    join(tmpdir(), "exifcleaner-isobmff-admission-"),
  );
  cleanupDirectories.push(directory);
  return directory;
}

async function writeFixture(
  bytes: Buffer,
): Promise<{ path: string; size: number }> {
  const directory = await freshDirectory();
  const path = join(directory, "input.heic");
  const handle = await open(path, "w");
  try {
    await handle.write(bytes, 0, bytes.length, 0);
  } finally {
    await handle.close();
  }
  return { path, size: bytes.length };
}

async function withHandle<T>(
  path: string,
  fn: (handle: FileHandle) => Promise<T>,
): Promise<T> {
  const handle = await open(path, "r");
  try {
    return await fn(handle);
  } finally {
    await handle.close();
  }
}

/** Minimal, structurally-valid XMP RDF payload (parseXmp requires balanced, entity-clean XML). */
function minimalXmp(title: string): Buffer {
  return Buffer.from(
    `<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">` +
      `<rdf:Description xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>${title}</dc:title></rdf:Description>` +
      `</rdf:RDF></x:xmpmeta>`,
    "utf8",
  );
}

/** A 4-byte `exif_tiff_header_offset` of 0, followed directly by a minimal TIFF/Exif payload. */
function exifItemPayload(): Buffer {
  const header = Buffer.alloc(4);
  return Buffer.concat([header, createOrientationExif(1)]);
}

interface ItemSpec {
  readonly itemId: number;
  readonly itemType: string;
  readonly hidden?: boolean;
  readonly contentType?: string;
  readonly contentEncoding?: string;
  /** D-14 regression (61-09): when `true`, writes no content_encoding bytes at all after
   * content_type (ISO/IEC 23008-12 9.2's OPTIONAL field, absent on the real iPhone 13 Pro Max
   * sample's XMP item). */
  readonly omitContentEncoding?: boolean;
  readonly constructionMethod?: number;
  readonly baseOffset?: number;
  readonly dataReferenceIndex?: number;
  /** cm=0: relative to the mdat payload's own start, resolved to an absolute `baseOffset` by the
   * builder (shared across every cm=0 item, mirroring the real `heif-enc` fixtures' own
   * base_offset-carries-the-absolute-position shape). cm=1: relative to the idat payload. */
  readonly extents: readonly {
    readonly relOffset: number;
    readonly length: number;
  }[];
  readonly propertyIndices?: readonly number[];
}

interface FileSpec {
  readonly offsetSize?: 0 | 4;
  readonly mdatFirst?: boolean;
  readonly majorBrand?: string;
  readonly compatibleBrands?: readonly string[];
  readonly primaryItemId: number;
  readonly items: readonly ItemSpec[];
  readonly properties?: readonly Buffer[];
  readonly refs?: readonly IrefRef[];
  readonly groups?: readonly GrplGroup[];
  readonly idatPayload?: Buffer;
  readonly mdatPayload: Buffer;
  /** Appended between `meta` and `mdat`. */
  readonly topLevelExtra?: readonly Buffer[];
  /** Appended after `mdat` (for the "meta/mdat not last" edge, D-10a's end-of-mdat variant). */
  readonly trailingExtra?: readonly Buffer[];
}

/**
 * Hand-built HEIF/AVIF-shaped file, two-pass (mirrors `builder.ts`'s own `heifFile` trick): an
 * `iloc` field's encoded byte length depends only on the declared widths, never the numeric values
 * stored, so a first pass with a placeholder `baseOffset` of 0 yields the real header length, which
 * is then used to compute every cm=0 item's real (shared) `baseOffset`.
 */
function buildFile(spec: FileSpec): Buffer {
  const assemble = (mdatPayloadStart: number): Buffer => {
    const ftyp = ftypBox(
      spec.majorBrand ?? "heic",
      0,
      spec.compatibleBrands ?? ["mif1", "heic"],
    );
    const hdlr = hdlrBox("pict");
    const pitm = pitmBox(0, spec.primaryItemId);
    const infeEntries = spec.items.map((item) =>
      infeBox({
        version: 2,
        itemId: item.itemId,
        itemType: item.itemType,
        ...(item.hidden !== undefined ? { hidden: item.hidden } : {}),
        ...(item.contentType !== undefined
          ? { contentType: item.contentType }
          : {}),
        ...(item.contentEncoding !== undefined
          ? { contentEncoding: item.contentEncoding }
          : {}),
        ...(item.omitContentEncoding === true
          ? { omitContentEncoding: true }
          : {}),
      }),
    );
    const iinf = iinfBox(0, infeEntries);
    const ipco = ipcoBox(spec.properties ?? []);
    const ipmaEntries = spec.items
      .filter((item) => (item.propertyIndices?.length ?? 0) > 0)
      .map((item) => ({
        itemId: item.itemId,
        associations: (item.propertyIndices ?? []).map((index) => ({
          propertyIndex: index,
          essential: false,
        })),
      }));
    const ipma = ipmaBox({ version: 0, flags: 0, entries: ipmaEntries });
    const iprp = iprpBox(ipco, ipma);
    const idat =
      spec.idatPayload !== undefined ? idatBox(spec.idatPayload) : undefined;
    const iloc = ilocBox({
      version: 1,
      offsetSize: spec.offsetSize ?? 4,
      lengthSize: 4,
      baseOffsetSize: 4,
      indexSize: 0,
      items: spec.items.map((item) => ({
        itemId: item.itemId,
        constructionMethod: item.constructionMethod ?? 0,
        dataReferenceIndex: item.dataReferenceIndex ?? 0,
        baseOffset:
          item.baseOffset ??
          ((item.constructionMethod ?? 0) === 0 ? mdatPayloadStart : 0),
        extents: item.extents.map((extent) => ({
          offset: extent.relOffset,
          length: extent.length,
        })),
      })),
    });
    const iref =
      spec.refs !== undefined && spec.refs.length > 0
        ? irefBox(0, spec.refs)
        : undefined;
    const grpl =
      spec.groups !== undefined && spec.groups.length > 0
        ? grplBox(spec.groups)
        : undefined;

    const metaChildren = [
      hdlr,
      pitm,
      ...(idat !== undefined ? [idat] : []),
      iloc,
      iinf,
      iprp,
      ...(iref !== undefined ? [iref] : []),
      ...(grpl !== undefined ? [grpl] : []),
    ];
    const meta = metaBox(metaChildren);
    const header = Buffer.concat([ftyp, meta, ...(spec.topLevelExtra ?? [])]);
    const mdat = mdatBox(spec.mdatPayload);
    if (spec.mdatFirst) return Buffer.concat([ftyp, mdat, meta]);
    return Buffer.concat([header, mdat, ...(spec.trailingExtra ?? [])]);
  };

  const pass1 = assemble(0);
  const mdatBoxTotal = 8 + spec.mdatPayload.length;
  const trailingLength = (spec.trailingExtra ?? []).reduce(
    (sum, box) => sum + box.length,
    0,
  );
  const headerLength = pass1.length - mdatBoxTotal - trailingLength;
  const mdatPayloadStart = spec.mdatFirst
    ? ftypBox(
        spec.majorBrand ?? "heic",
        0,
        spec.compatibleBrands ?? ["mif1", "heic"],
      ).length + 8
    : headerLength + 8;
  const final = assemble(mdatPayloadStart);
  if (final.length !== pass1.length) {
    throw new Error(
      "buildFile: header length changed between placeholder and final passes",
    );
  }
  return final;
}

describe("src/isobmff/admission.ts exports", () => {
  it("exports admitIsobmff, classifyIsobmffModel, DECLINE_RULE_ORDER, PRESERVED_ITEM_TYPES, XMP_CONTENT_TYPES", () => {
    expect(typeof admitIsobmff).toBe("function");
    expect(typeof classifyIsobmffModel).toBe("function");
    expect(DECLINE_RULE_ORDER.length).toBe(10);
    expect(PRESERVED_ITEM_TYPES.has("hvc1")).toBe(true);
    expect(XMP_CONTENT_TYPES).toEqual(["application/rdf+xml"]);
  });
});

describe("admitIsobmff on real heif-enc fixtures (Task 1 tracer, Task 2)", () => {
  it("admits heif-enc-grid.heic with the measured Exif/XMP removable ids and real entries", async () => {
    const admission = await withHandle(HEIC_PATH, (handle) =>
      admitIsobmff(handle, 4243),
    );
    expect(admission.classification.removableItemIds).toEqual([6, 7]);
    expect(admission.classification.emptiedItemIds).toEqual([]);
    expect(admission.classification.survivingItemIds).toEqual([
      1, 2, 3, 4, 5, 8,
    ]);
    expect(admission.namespaces).toContain("EXIF");
    expect(admission.namespaces).toContain("XMP");
    expect(
      admission.entries.some(
        (entry) =>
          entry.name === "Make" && entry.value === "ExifCleanerFixture",
      ),
    ).toBe(true);
  });

  it("admits heif-enc-grid.avif with the measured Exif/XMP removable ids", async () => {
    const admission = await withHandle(AVIF_PATH, (handle) =>
      admitIsobmff(handle, 3997),
    );
    expect(admission.classification.removableItemIds).toEqual([6, 7]);
    expect(admission.classification.emptiedItemIds).toEqual([]);
    expect(admission.classification.survivingItemIds).toEqual([
      1, 2, 3, 4, 5, 8,
    ]);
    expect(admission.namespaces).toContain("EXIF");
    expect(admission.namespaces).toContain("XMP");
  });
});

describe("the measured iPhone shape (builder, D-08/D-09)", () => {
  it("admits a grid-in-idat primary with hidden tiles, a thumbnail, an hdrgainmap auxl, and cdsc-from-item Exif/XMP", async () => {
    const idatPayload = Buffer.from([0, 0, 0, 0, 0, 0, 0, 1]); // grid descriptor bytes (opaque)
    const tilePayload = Buffer.from("tile-bytes", "ascii");
    const thumbPayload = Buffer.from("thumb-bytes", "ascii");
    const exifPayload = exifItemPayload();
    const xmpPayload = minimalXmp("iPhone shape");

    const spec: FileSpec = {
      primaryItemId: 1,
      items: [
        {
          itemId: 1,
          itemType: "grid",
          constructionMethod: 1,
          extents: [{ relOffset: 0, length: idatPayload.length }],
        },
        {
          itemId: 2,
          itemType: "hvc1",
          hidden: true,
          extents: [{ relOffset: 0, length: tilePayload.length }],
        },
        {
          itemId: 3,
          itemType: "hvc1",
          hidden: false,
          extents: [
            {
              relOffset: tilePayload.length,
              length: thumbPayload.length,
            },
          ],
        },
        {
          itemId: 4,
          itemType: "hvc1",
          hidden: true,
          propertyIndices: [1],
          extents: [
            {
              relOffset: tilePayload.length + thumbPayload.length,
              length: tilePayload.length,
            },
          ],
        },
        {
          itemId: 5,
          itemType: "Exif",
          hidden: true,
          extents: [
            {
              relOffset: 2 * tilePayload.length + thumbPayload.length,
              length: exifPayload.length,
            },
          ],
        },
        {
          itemId: 6,
          itemType: "mime",
          hidden: true,
          contentType: "application/rdf+xml",
          contentEncoding: "",
          extents: [
            {
              relOffset:
                2 * tilePayload.length +
                thumbPayload.length +
                exifPayload.length,
              length: xmpPayload.length,
            },
          ],
        },
      ],
      // auxC property (index 1), carrying the Apple HDR gain-map URN.
      properties: [auxC("urn:com:apple:photo:2020:aux:hdrgainmap")],
      refs: [
        { type: "dimg", fromItemId: 1, toItemIds: [2] },
        { type: "thmb", fromItemId: 3, toItemIds: [1] },
        { type: "auxl", fromItemId: 4, toItemIds: [1] },
        { type: "cdsc", fromItemId: 5, toItemIds: [1] },
        { type: "cdsc", fromItemId: 6, toItemIds: [1] },
      ],
      idatPayload,
      mdatPayload: Buffer.concat([
        tilePayload,
        thumbPayload,
        tilePayload,
        exifPayload,
        xmpPayload,
      ]),
    };

    const bytes = buildFile(spec);
    const { path, size } = await writeFixture(bytes);
    const admission = await withHandle(path, (handle) =>
      admitIsobmff(handle, size),
    );

    expect(admission.classification.survivingItemIds).toEqual([1, 2, 3, 4]);
    expect(admission.classification.removableItemIds).toEqual([5, 6]);
    expect(admission.classification.emptiedItemIds).toEqual([]);
    expect(admission.namespaces).toContain("EXIF");
    expect(admission.namespaces).toContain("XMP");
  });
});

describe("D-14 regression: mime infe with absent content_encoding (61-09, orchestrator-added)", () => {
  it("admits the XMP item (removable, non-emptied) exactly like the explicit-empty-string shape", async () => {
    const primaryPayload = Buffer.from([1, 2, 3, 4]);
    const xmpPayload = minimalXmp("absent-content-encoding");
    const spec: FileSpec = {
      primaryItemId: 1,
      items: [
        {
          itemId: 1,
          itemType: "hvc1",
          extents: [{ relOffset: 0, length: primaryPayload.length }],
        },
        {
          itemId: 2,
          itemType: "mime",
          hidden: true,
          contentType: "application/rdf+xml",
          omitContentEncoding: true,
          extents: [
            { relOffset: primaryPayload.length, length: xmpPayload.length },
          ],
        },
      ],
      mdatPayload: Buffer.concat([primaryPayload, xmpPayload]),
    };
    const bytes = buildFile(spec);
    const { path, size } = await writeFixture(bytes);
    const admission = await withHandle(path, (handle) =>
      admitIsobmff(handle, size),
    );

    expect(admission.classification.survivingItemIds).toEqual([1]);
    expect(admission.classification.removableItemIds).toEqual([2]);
    expect(admission.classification.emptiedItemIds).toEqual([]);
    expect(admission.namespaces).toContain("XMP");
  });
});

describe("D-10a: empty extents and extent_count 0 (amended)", () => {
  async function buildEmptyExif(options: {
    readonly relOffset: number;
    readonly mdatLength: number;
    readonly trailingExtra?: readonly Buffer[];
  }): Promise<{ path: string; size: number }> {
    const survivingPayload = Buffer.from("surviving-tile-bytes", "ascii");
    const spec: FileSpec = {
      primaryItemId: 1,
      items: [
        {
          itemId: 1,
          itemType: "hvc1",
          extents: [{ relOffset: 0, length: survivingPayload.length }],
        },
        {
          itemId: 2,
          itemType: "Exif",
          hidden: true,
          extents: [{ relOffset: options.relOffset, length: 0 }],
        },
      ],
      mdatPayload: Buffer.concat([
        survivingPayload,
        Buffer.alloc(Math.max(0, options.mdatLength - survivingPayload.length)),
      ]),
      ...(options.trailingExtra !== undefined
        ? { trailingExtra: options.trailingExtra }
        : {}),
    };
    const bytes = buildFile(spec);
    return writeFixture(bytes);
  }

  it("admits a removable zero-length extent at offset == file size (EOF variant), listed in emptiedItemIds", async () => {
    // Choose relOffset == mdatPayload length so the absolute offset lands exactly at the end of
    // mdat, which (with no trailing boxes) is also the file's own end.
    const mdatLength = 32;
    const { path, size } = await buildEmptyExif({
      relOffset: mdatLength,
      mdatLength,
    });
    const admission = await withHandle(path, (handle) =>
      admitIsobmff(handle, size),
    );
    expect(admission.classification.removableItemIds).toEqual([2]);
    expect(admission.classification.emptiedItemIds).toEqual([2]);
  });

  it("admits a removable zero-length extent at offset == end of mdat, with a trailing free box after it (end-of-mdat variant)", async () => {
    const mdatLength = 32;
    const freeBox = Buffer.concat([
      Buffer.from([0, 0, 0, 8]),
      Buffer.from("free", "ascii"),
    ]);
    const { path, size } = await buildEmptyExif({
      relOffset: mdatLength,
      mdatLength,
      trailingExtra: [freeBox],
