          ],
        },
        {
          itemId: 4,
          itemType: "hvc1",
          hidden: true,
          propertyIndices: [1],
          extents: [
            {
              relOffset: tilePayload.length + thumbPayload.length,
              length: tilePayload.length,
            },
          ],
        },
        {
          itemId: 5,
          itemType: "Exif",
          hidden: true,
          extents: [
            {
