        items: [image, exif([{ relOffset: 4, length }])],
        mdatPayload: Buffer.alloc(4 + length),
      });
      expect(result.namespaces).toEqual(["EXIF"]);
      expect(result.warnings.map((warning) => warning.code)).toEqual(
        length === 3 ? [] : ["metadata-invalid"],
      );
    }
  });
  it("admitIsobmff ArithmeticOperator: nonzero TIFF padding preserves source orientation", async () => {
    const payload = Buffer.concat([
      Buffer.from([0, 0, 0, 8]),
      Buffer.alloc(8),
      createOrientationExif(8),
    ]);
    const result = await admit({
      primaryItemId: 1,
      items: [image, exif([{ relOffset: 4, length: payload.length }])],
      refs: [{ type: "cdsc", fromItemId: 2, toItemIds: [1] }],
      mdatPayload: Buffer.concat([Buffer.alloc(4), payload]),
    });
    expect(result.exifSourceItemId).toBe(2);
    expect(result.orientation).toEqual({ status: "valid", value: 8 });
  });
  it("admitIsobmff ConditionalExpression BlockStatement BooleanLiteral: abort between removable reads is a typed framing failure", async () => {
    const payload = exifItemPayload();
    const bytes = buildFile({
      primaryItemId: 1,
      items: [
        image,
        exif([{ relOffset: 4, length: payload.length }]),
        {
          itemId: 3,
          itemType: "mime",
          contentType: "application/rdf+xml",
          extents: [{ relOffset: 4 + payload.length, length: 1 }],
        },
      ],
      mdatPayload: Buffer.concat([
        Buffer.alloc(4),
        payload,
        Buffer.from([255]),
      ]),
    });
    const { path, size } = await writeFixture(bytes);
    await withHandle(path, async (handle) => {
      const model = await parseIsobmff(handle, size);
      const item = model.itemsById.get(2)!;
      const position = item.baseOffset + item.extents[0]!.offset;
      const controller = new AbortController();
      const intercepted = new Proxy(handle, {
        get(target, key) {
          if (key === "read")
            return async (...args: [Buffer, number, number, number]) => {
              const result = await target.read(...args);
              if (args[3] === position) controller.abort();
              return result;
            };
          const value: unknown = Reflect.get(target, key, target);
          return typeof value === "function" ? value.bind(target) : value;
        },
      });
      await expect(
        admitIsobmff(intercepted, size, controller.signal),
      ).rejects.toMatchObject({
        declineClass: "box-framing",
        kind: "malformed-file",
      });
      expect(controller.signal.aborted).toBe(true);
    });
  });
});

tests/isobmff_negative_controls.test.ts.source:
// D-19 (62-10): the identity proof (D-18, 62-09) has teeth -- a flipped byte in a surviving item,
// and each of the five named writer mutants, are caught before publication, with nothing
// published and the source preserved. Every mutant lives in the one declared test seam
// (`tests/isobmff-support/test-handler.ts`, D-19's own isolation rule) and acts on the frozen
// `IsobmffOutputPlan` or the written destination bytes only -- this file never touches `src/`.
import {
  mkdtemp,
  open,
  readdir,
  readFile,
  rm,
  stat,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";
import { sanitizeFile } from "../src/engine.js";
import { setRegisteredHandlersForTests } from "../src/admission/registry.js";
import { admitIsobmff } from "../src/isobmff/admission.js";
import { IsobmffStructureError } from "../src/isobmff/errors.js";
import type { IsobmffOutputPlan } from "../src/isobmff/plan.js";
import { colrProf, ispe, pixi } from "./isobmff-support/builder.js";
import { assembleHeif } from "./isobmff-support/hostile.js";
import {
  createFlipOneByteHandler,
  createIsobmffWriterHandlerForTests,
  createPlanMutantHandler,
  mutateIlocOffsetShiftSkipped,
  mutateIlocWidthsNormalizedToEight,
  mutateIpmaRemapOffByOne,
  mutateMdatKeepRemovedRange,
  mutateMinimalExifConstructionMethodOne,
} from "./isobmff-support/test-handler.js";

const FIXTURES_DIR = join(
  dirname(fileURLToPath(import.meta.url)),
  "corpus",
  "constructed",
);
const HEIC_FIXTURE = join(FIXTURES_DIR, "heic", "heif-enc-grid.heic");

/** The preservation flags every heif-enc-grid.heic case uses -- the same "default settings" 62-07
 * already measured synthesize exactly one minimal Exif item (id 6) at the mdat tail. */
const DEFAULT_PRESERVATION = {
  preserveOrientation: true,
  preserveColorProfile: true,
  preserveTimestamps: true,
  preserveResolution: true,
} as const;

const directories: string[] = [];
afterEach(async () => {
  await Promise.all(
    directories
      .splice(0)
      .map((directory) => rm(directory, { recursive: true, force: true })),
  );
});

async function freshDirectory(): Promise<string> {
  const directory = await mkdtemp(
    join(tmpdir(), "exifcleaner-isobmff-negative-"),
  );
  directories.push(directory);
  return directory;
}

/** A single `hvc1` primary item carrying three `ipco` properties (ispe, a `colr prof` ICC
 * property, and `pixi`) so that sanitizing with `preserveColorProfile: false` removes the middle
 * property and non-trivially remaps the surviving associations (D-16) -- the fixture
 * `mutateIpmaRemapOffByOne` needs to make its "+1" corruption land on a real, different property. */
function buildIccRemapFixture(): Buffer {
  const primaryPayload = Buffer.from("rgb-primary-tile-bytes", "ascii");
  return assembleHeif({
    primaryItemId: 1,
    items: [
      {
        itemId: 1,
        itemType: "hvc1",
        extents: [{ relOffset: 0, length: primaryPayload.length }],
        propertyIndices: [1, 2, 3],
      },
    ],
    properties: [
      ispe(32, 32),
      colrProf(Buffer.from([9, 9, 9, 9])),
      pixi([8, 8, 8]),
    ],
    mdatPayload: primaryPayload,
    twoPass: true,
  });
}

/**
 * Runs `sanitizeFile` with a single `createPlanMutantHandler(createIsobmffWriterHandlerForTests
 * (brand), mutate)` installed as the only registered handler, against a fresh copy of
 * `sourceBytes`. Returns everything a case needs to assert "not-ok, destination absent, source
 * unchanged" without repeating the directory/file bookkeeping in every test.
 */
async function runWithMutant(
  sourceBytes: Buffer,
  brand: "heic" | "avif",
  mutate: (plan: IsobmffOutputPlan) => IsobmffOutputPlan,
  overrides: Partial<Parameters<typeof sanitizeFile>[0]> = {},
): Promise<{
  readonly sanitized: Awaited<ReturnType<typeof sanitizeFile>>;
  readonly directory: string;
  readonly sourceName: string;
  readonly destinationName: string;
  readonly sourcePath: string;
  readonly sourceSnapshot: Buffer;
}> {
  const directory = await freshDirectory();
  const sourceName = `source.${brand}`;
  const destinationName = `destination.${brand}`;
  const sourcePath = join(directory, sourceName);
  await writeFile(sourcePath, sourceBytes);
  const sourceSnapshot = await readFile(sourcePath);
  const destinationPath = join(directory, destinationName);

  const inner = createIsobmffWriterHandlerForTests(brand);
  const restore = setRegisteredHandlersForTests([
    createPlanMutantHandler(inner, mutate),
  ]);
  try {
    const sanitized = await sanitizeFile({
      sourcePath,
      destinationPath,
      ...DEFAULT_PRESERVATION,
      ...overrides,
    });
    return {
      sanitized,
      directory,
      sourceName,
      destinationName,
      sourcePath,
      sourceSnapshot,
    };
  } finally {
    restore();
  }
}

/**
 * Asserts the directory holds the source and, at most, the engine's own private stage
 * directory/file (`.exifcleaner-stage-<uuid>`, `src/transaction/safe-transaction.ts`) -- a failed
 * verification never renames that private, 0700-permission directory to the public destination
 * path, so no entry is ever the public destination filename, but the private directory itself is
 * documented, pre-existing residue of a non-committed run (see e.g. `tests/safe_transaction.test
 * .ts`'s "owned-partial-remains" case) that this test-only plan does not touch (`src/transaction/
 * **` is out of scope, 62-CONTEXT.md). "Nothing is published" is the claim this proves -- not
 * "the stage directory is swept," which is `src/transaction/safe-transaction.ts`'s own concern.
 */
async function expectNothingPublished(
  directory: string,
  sourceName: string,
  destinationName: string,
): Promise<void> {
  const listing = await readdir(directory);
  expect(listing).toContain(sourceName);
  expect(listing).not.toContain(destinationName);
  for (const entry of listing) {
    if (entry === sourceName) continue;
    expect(entry.startsWith(".exifcleaner-stage-")).toBe(true);
  }
}

/** Shared assertion for every red mutant case: `sanitizeFile` failed with `verification-failed`,
 * nothing was published, and the source bytes are unchanged. */
async function expectRed(
  result: Awaited<ReturnType<typeof runWithMutant>>,
): Promise<void> {
  const {
    sanitized,
    directory,
    sourceName,
    destinationName,
    sourcePath,
    sourceSnapshot,
  } = result;
  expect(sanitized.ok).toBe(false);
  if (sanitized.ok) throw new Error("unreachable");
  expect(sanitized.error.code).toBe("verification-failed");

  await expectNothingPublished(directory, sourceName, destinationName);

  const sourceAfter = await readFile(sourcePath);
  expect(sourceAfter.equals(sourceSnapshot)).toBe(true);
}

describe("D-19 flip-one-byte (62-10)", () => {
  it.each([["first" as const], ["last" as const], ["none" as const]])(
    "heif-enc-grid.heic, flip position %s",
    async (position) => {
      const directory = await freshDirectory();
      const sourceName = "source.heic";
      const sourcePath = join(directory, sourceName);
      await writeFile(sourcePath, await readFile(HEIC_FIXTURE));
      const sourceSnapshot = await readFile(sourcePath);
      const destinationPath = join(directory, "destination.heic");

      const inner = createIsobmffWriterHandlerForTests("heic");
      const restore = setRegisteredHandlersForTests([
        createFlipOneByteHandler(inner, { position }),
      ]);
      try {
        const sanitized = await sanitizeFile({
          sourcePath,
          destinationPath,
          ...DEFAULT_PRESERVATION,
        });

        if (position === "none") {
          expect(sanitized.ok).toBe(true);
          const listing = await readdir(directory);
          expect(listing.sort()).toEqual(["destination.heic", "source.heic"]);
          return;
        }

        expect(sanitized.ok).toBe(false);
        if (sanitized.ok) throw new Error("unreachable");
        expect(sanitized.error.code).toBe("verification-failed");

        await expectNothingPublished(directory, sourceName, "destination.heic");

        const sourceAfter = await readFile(sourcePath);
        expect(sourceAfter.equals(sourceSnapshot)).toBe(true);
      } finally {
        restore();
      }
    },
  );
});

describe("D-19 writer mutants (62-10)", () => {
  const HEIF_ENC_CASES = [
    ["offset shift skipped", mutateIlocOffsetShiftSkipped, false] as const,
    [
      "one removed range kept in the mdat copy ranges",
      mutateMdatKeepRemovedRange,
      false,
    ] as const,
    [
      "iloc widths normalized to 8",
      mutateIlocWidthsNormalizedToEight,
      false,
    ] as const,
    [
      "minimal Exif written to idat with construction method 1",
      mutateMinimalExifConstructionMethodOne,
      false,
    ] as const,
    [
      "identity mutant control",
      (plan: IsobmffOutputPlan) => plan,
      true,
    ] as const,
  ];

  it.each(HEIF_ENC_CASES)("%s", async (_name, mutate, expectOk) => {
    const sourceBytes = await readFile(HEIC_FIXTURE);
    const result = await runWithMutant(sourceBytes, "heic", mutate);

    if (expectOk) {
      expect(result.sanitized.ok).toBe(true);
      const listing = await readdir(result.directory);
      expect(listing.sort()).toEqual(["destination.heic", "source.heic"]);
      return;
    }

    await expectRed(result);
  });

  it("ipma remap off by one (ICC fixture, preserveColorProfile false)", async () => {
    const sourceBytes = buildIccRemapFixture();
    const result = await runWithMutant(
      sourceBytes,
      "heic",
      mutateIpmaRemapOffByOne,
      {
        preserveOrientation: false,
        preserveColorProfile: false,
        preserveTimestamps: false,
        preserveResolution: false,
      },
    );

    await expectRed(result);
  });

  it(
    "mutant 5 re-clean: a minimal Exif item placed in idat (cm=1) declines " +
      "removable-item-in-idat on re-clean, so clean(clean(x)) cannot equal clean(x)",
    async () => {
      const directory = await freshDirectory();
      const sourcePath = join(directory, "source.heic");
      await writeFile(sourcePath, await readFile(HEIC_FIXTURE));
      const { size } = await stat(sourcePath);
      const mutantOutputPath = join(directory, "mutant-output.heic");

      const inner = createIsobmffWriterHandlerForTests("heic");
      const sourceHandle = await open(sourcePath, "r");
      try {
        const admission = await inner.admit(sourceHandle, size);
        const orientationValue =
          admission.orientation.status === "valid"
            ? admission.orientation.value
            : undefined;
        const plan = mutateMinimalExifConstructionMethodOne(
          inner.buildOutputPlan(
            admission,
            true,
            true,
            true,
            orientationValue,
          ) as IsobmffOutputPlan,
        );

        // Written directly to a temp file OUTSIDE the normal safe-transaction/verify pipeline --
        // this file is deliberately never cleaned up by a failed verify, so re-clean below has
        // something to read.
        const mutantHandle = await open(mutantOutputPath, "w");
        try {
          await inner.writeOutput(sourceHandle, mutantHandle, plan, undefined);
        } finally {
          await mutantHandle.close();
        }
      } finally {
        await sourceHandle.close();
      }

      // Direct admission re-check: the mutant output's own minimal Exif item (k, construction
      // method 1) is classified "removable" on fresh admission (every Exif item is), and D3's
      // rule 5 declines any removable item whose construction_method is not 0 -- the exact class
      // named by this mutant.
      const mutantHandle = await open(mutantOutputPath, "r");
      let declineClass: string | undefined;
      try {
        const { size: mutantSize } = await stat(mutantOutputPath);
        await admitIsobmff(mutantHandle, mutantSize);
        throw new Error(
          "admitIsobmff unexpectedly admitted the mutant output.",
        );
      } catch (cause) {
        if (cause instanceof IsobmffStructureError) {
          declineClass = cause.declineClass;
        } else {
          throw cause;
        }
      } finally {
        await mutantHandle.close();
      }
      expect(declineClass).toBe("removable-item-in-idat");

      // Re-clean through the full engine too: sanitizing the mutant output with the real writer
      // handler must fail (not publish a second, different "clean" result), proving
      // clean(clean(x)) cannot equal clean(x) for this mutant.
      const restore = setRegisteredHandlersForTests([
        createIsobmffWriterHandlerForTests("heic"),
      ]);
      try {
        const reCleanedPath = join(directory, "re-cleaned.heic");
        const reCleaned = await sanitizeFile({
          sourcePath: mutantOutputPath,
          destinationPath: reCleanedPath,
          ...DEFAULT_PRESERVATION,
        });
        expect(reCleaned.ok).toBe(false);
        if (reCleaned.ok) throw new Error("unreachable");
        expect(reCleaned.error.code).toBe("unsupported-format");
        expect(reCleaned.error.detail).toContain("construction_method");
      } finally {
        restore();
      }
    },
  );
});

tests/isobmff_proof_harness.test.ts.source:
// D-16/61-10: proves through the REAL engine (never a pure-classifier-only check) that:
//
//   - success criterion 4 -- every one of the 24 `IsobmffDeclineClass` hostile fixtures declines
//     exactly once, before any write, safe to fall back;
//   - success criterion 3 -- HEIC/AVIF are recognized through the widened (256-byte) registry
//     read, both on real `heif-enc` encoder output and on a brand placed past the pre-D-17 12-byte
//     window.
//
// The test-only handler (`createIsobmffTestHandler`, `tests/isobmff-support/test-handler.ts`) is
// installed ADDITIVELY alongside the real `webpHandler`/`pngHandler`/`jpegHandler` via the existing
// private `setRegisteredHandlersForTests` seam, and always restored in `finally` -- the registry
// must never observe our test handler outside the scope of a single test.
import {
  mkdtemp,
  open,
  readdir,
  readFile,
  rm,
  writeFile,
} from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";
import { inspectFile, sanitizeFile } from "../src/engine.js";
import {
  registeredHandlersForTests,
  selectHandler,
  setRegisteredHandlersForTests,
} from "../src/admission/registry.js";
import type { RegisteredHandler } from "../src/admission/registry.js";
import { webpHandler } from "../src/admission/webp-handler.js";
import { pngHandler } from "../src/admission/png-handler.js";
import { jpegHandler } from "../src/admission/jpeg-handler.js";
// D-13: `classifyFallback` (src/fallback.ts:3-7) keys ONLY on `error.phase` and
// `error.nativeWrite` -- never on `error.code` -- so the per-class public code asserted below is
// pinned entirely by this test file's own `.toMatchObject({ code: ... })` assertions, not by
// anything `classifyFallback` itself checks. The app never branches on the ISOBMFF-specific code
// either (D-13's other traced call sites), so a wrong code here would be caught only by these
// tests, never by the app's own runtime behavior.
import { classifyFallback } from "../src/fallback.js";
import { ISOBMFF_DECLINE_CLASSES } from "../src/isobmff/errors.js";
import { assembleHeif, HOSTILE_FIXTURES } from "./isobmff-support/hostile.js";
import { colrProf } from "./isobmff-support/builder.js";
import {
  createIsobmffTestHandler,
  createIsobmffWriterCountingHandlerForTests,
} from "./isobmff-support/test-handler.js";
import { metadataJpeg, metadataPng, metadataWebp } from "./fixtures.js";

const FIXTURES_DIR = join(
  dirname(fileURLToPath(import.meta.url)),
  "corpus",
  "constructed",
);
const HEIC_PATH = join(FIXTURES_DIR, "heic", "heif-enc-grid.heic");
const AVIF_PATH = join(FIXTURES_DIR, "avif", "heif-enc-grid.avif");

/** D-16: hostile runs use no preservation options at all, so only admission decides. */
const NO_PRESERVATION = {
  preserveOrientation: false,
  preserveColorProfile: false,
  preserveTimestamps: false,
  preserveResolution: false,
} as const;

const directories: string[] = [];

afterEach(async () => {
  await Promise.all(
    directories
      .splice(0)
      .map((directory) => rm(directory, { recursive: true, force: true })),
  );
});

async function freshDirectory(): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "exifcleaner-isobmff-"));
  directories.push(directory);
  return directory;
}

async function writeBytesTo(path: string, bytes: Buffer): Promise<void> {
  const handle = await open(path, "w");
  try {
    await handle.write(bytes, 0, bytes.length, 0);
  } finally {
    await handle.close();
  }
}

async function selectThroughRealRegistry(
  path: string,
): Promise<RegisteredHandler | undefined> {
  const handle: FileHandle = await open(path, "r");
  try {
    return await selectHandler(handle);
  } finally {
    await handle.close();
  }
}

function installTestHandlerAdditively() {
  const { handler, counters } = createIsobmffTestHandler();
  const restore = setRegisteredHandlersForTests([
    // Prepended, not appended: since 62.1-07 registered the real heic/avif handlers, an
    // appended stub would never be selected for an ISOBMFF file (first match wins).
    handler,
    ...registeredHandlersForTests(),
  ]);
  return { handler, counters, restore };
}

describe("Task 1 tracer: one hostile class (removable-item-in-idat) through the real engine", () => {
  it("declines once, before any write, safe to fall back -- the full D-16 assertion set", async () => {
    const fixture = HOSTILE_FIXTURES["removable-item-in-idat"];
    expect(fixture.stage).toBe("admission");

    const directory = await freshDirectory();
    const sourceName = "source.bin";
    const sourcePath = join(directory, sourceName);
    const destinationPath = join(directory, "destination.bin");
    await fixture.write(sourcePath);
    const sourceBytes = await readFile(sourcePath);

    const { counters, restore } = installTestHandlerAdditively();
    try {
      const sanitized = await sanitizeFile({
        sourcePath,
        destinationPath,
        ...NO_PRESERVATION,
      });
      expect(sanitized.ok).toBe(false);
      if (sanitized.ok) throw new Error("unreachable");
      expect(sanitized.error).toMatchObject({
        code: fixture.expectedCode,
        phase: "admission",
        nativeWrite: "not-started",
      });
      expect(classifyFallback(sanitized.error)).toBe("safe-to-fallback");

      expect(counters.admit).toBe(1);
      expect(counters.buildOutputPlan).toBe(0);
      expect(counters.checkOutputPlan).toBe(0);
      expect(counters.writeOutput).toBe(0);
      expect(counters.verifyOutput).toBe(0);

      const listing = await readdir(directory);
      expect(listing).toEqual([sourceName]);

      const sourceAfter = await readFile(sourcePath);
      expect(sourceAfter.equals(sourceBytes)).toBe(true);

      const inspected = await inspectFile(sourcePath);
      expect(inspected.ok).toBe(false);
      if (inspected.ok) throw new Error("unreachable");
      expect(inspected.error).toMatchObject({
        code: fixture.expectedCode,
        phase: "admission",
      });
    } finally {
      restore();
    }
  });
});

describe("Task 2: every ISOBMFF decline class declines once before any write (BMF-03/D-16)", () => {
  it.each(ISOBMFF_DECLINE_CLASSES)(
    "%s declines through the real engine, safe to fall back",
    async (declineClass) => {
      const fixture = HOSTILE_FIXTURES[declineClass];
      const directory = await freshDirectory();
      const sourceName = "source.bin";
      const sourcePath = join(directory, sourceName);
      const destinationPath = join(directory, "destination.bin");
      await fixture.write(sourcePath);
      const sourceBytes = await readFile(sourcePath);

      if (fixture.stage === "plan") {
        // 62-05 (D-12): a "plan"-stage fixture admits cleanly -- the decline happens one stage
        // later, inside `checkOutputPlan`, which can only be observed by running the REAL writer
        // handler (never the admission-only counting stub every other stage uses).
        const { handler, counters } =
          createIsobmffWriterCountingHandlerForTests("heic");
        const restore = setRegisteredHandlersForTests([handler]);
        try {
          const sanitized = await sanitizeFile({
            sourcePath,
            destinationPath,
            ...NO_PRESERVATION,
          });
          expect(sanitized.ok).toBe(false);
          if (sanitized.ok) throw new Error("unreachable");
          expect(sanitized.error).toMatchObject({
            code: fixture.expectedCode,
            phase: "admission",
            nativeWrite: "not-started",
          });
          expect(classifyFallback(sanitized.error)).toBe("safe-to-fallback");

          expect(counters.admit).toBe(1);
          expect(counters.buildOutputPlan).toBe(1);
          expect(counters.checkOutputPlan).toBe(1);
          expect(counters.writeOutput).toBe(0);
          expect(counters.verifyOutput).toBe(0);

          const listing = await readdir(directory);
          expect(listing).toEqual([sourceName]);

          const sourceAfter = await readFile(sourcePath);
          expect(sourceAfter.equals(sourceBytes)).toBe(true);
        } finally {
          restore();
        }
        return;
      }

      if (fixture.stage === "handler") {
        // D-09(b) (62-12): a "handler"-stage fixture (currently `brand-mismatch` only) is a
        // structurally valid, fully admittable file of the OTHER brand -- `matches` on the
        // mismatched handler already returns false for it, so a normal `sanitizeFile`/
        // `selectHandler` run never reaches this handler's `admit` at all. The decline is observed
        // only by calling the mismatched (heic) handler's own `admit` directly, simulating a file
        // swapped between selection and admission; `buildOutputPlan`/`checkOutputPlan`/
        // `writeOutput`/`verifyOutput` are never reached.
        const { handler, counters } =
          createIsobmffWriterCountingHandlerForTests("heic");
        const handle = await open(sourcePath, "r");
        try {
          await expect(
            handler.admit(handle, sourceBytes.length),
          ).rejects.toMatchObject({
            declineClass,
            kind: fixture.expectedCode,
          });
          expect(counters.admit).toBe(1);
          expect(counters.buildOutputPlan).toBe(0);
          expect(counters.checkOutputPlan).toBe(0);
          expect(counters.writeOutput).toBe(0);
          expect(counters.verifyOutput).toBe(0);
        } finally {
          await handle.close();
        }

        const listing = await readdir(directory);
        expect(listing).toEqual([sourceName]);
        const sourceAfter = await readFile(sourcePath);
        expect(sourceAfter.equals(sourceBytes)).toBe(true);
        return;
      }

      const { counters, restore } = installTestHandlerAdditively();
      try {
        const sanitized = await sanitizeFile({
          sourcePath,
          destinationPath,
          ...NO_PRESERVATION,
        });
        expect(sanitized.ok).toBe(false);
        if (sanitized.ok) throw new Error("unreachable");
        expect(sanitized.error).toMatchObject({
          code: fixture.expectedCode,
          phase: "admission",
          nativeWrite: "not-started",
        });
        expect(classifyFallback(sanitized.error)).toBe("safe-to-fallback");

        if (fixture.stage === "selection") {
          // D-12: a non-matching brand never reaches our handler's `admit` at all -- it is the
          // existing no-handler decline (`src/engine.ts`), already safe to fall back.
          expect(counters.admit).toBe(0);
        } else {
          expect(counters.admit).toBe(1);
        }
        expect(counters.buildOutputPlan).toBe(0);
        expect(counters.checkOutputPlan).toBe(0);
        expect(counters.writeOutput).toBe(0);
        expect(counters.verifyOutput).toBe(0);

        const listing = await readdir(directory);
        expect(listing).toEqual([sourceName]);

        const sourceAfter = await readFile(sourcePath);
        expect(sourceAfter.equals(sourceBytes)).toBe(true);

        if (fixture.stage === "admission") {
          const inspected = await inspectFile(sourcePath);
          expect(inspected.ok).toBe(false);
          if (inspected.ok) throw new Error("unreachable");
          expect(inspected.error).toMatchObject({
            code: fixture.expectedCode,
            phase: "admission",
          });
        }
      } finally {
        restore();
      }
    },
  );

  it("ICC carve-out: an invalid primary colr ICC declines unsupported-feature/color-profile-preservation at admission, not as an IsobmffStructureError", async () => {
    // D-12's explicit carve-out: ICC-preservation failure is never an `IsobmffStructureError` --
    // the engine (src/engine.ts:186-198) declines it once `admission.colorProfile` is set, using
    // the same `validateIccForPreservation` policy every other format shares.
    const invalidIcc = Buffer.from("not-a-real-icc-profile", "ascii");
    const primaryPayload = Buffer.from([1, 2, 3, 4]);
    const bytes = assembleHeif({
      items: [
        {
          itemId: 1,
          itemType: "hvc1",
          extents: [{ relOffset: 0, length: primaryPayload.length }],
          propertyIndices: [1],
        },
      ],
      properties: [colrProf(invalidIcc)],
      mdatPayload: primaryPayload,
      twoPass: true,
    });

    const directory = await freshDirectory();
    const sourceName = "source.bin";
    const sourcePath = join(directory, sourceName);
    const destinationPath = join(directory, "destination.bin");
    await writeBytesTo(sourcePath, bytes);

    const { counters, restore } = installTestHandlerAdditively();
    try {
      const sanitized = await sanitizeFile({
        sourcePath,
        destinationPath,
        preserveOrientation: false,
        preserveColorProfile: true,
        preserveTimestamps: false,
        preserveResolution: false,
      });
      expect(sanitized.ok).toBe(false);
      if (sanitized.ok) throw new Error("unreachable");
      expect(sanitized.error).toMatchObject({
        code: "unsupported-feature",
        feature: "color-profile-preservation",
        phase: "admission",
        nativeWrite: "not-started",
      });
      expect(classifyFallback(sanitized.error)).toBe("safe-to-fallback");
      expect(counters.admit).toBe(1);
      expect(counters.writeOutput).toBe(0);
      expect(counters.buildOutputPlan).toBe(0);
      expect(counters.checkOutputPlan).toBe(0);
      expect(counters.verifyOutput).toBe(0);

      // The ICC policy applies only to preservation: the same file inspects clean (no
      // IsobmffStructureError, no decline at all) because inspectFile never validates the ICC
      // payload for preservation -- it only reports what is present.
      const inspected = await inspectFile(sourcePath);
      expect(inspected.ok).toBe(true);
    } finally {
      restore();
    }
  });

  it("positive recognition (success criterion 3): heif-enc-grid.heic/avif and a mif1/miaf/MA1B/avif brand past byte 12 all inspect ok through the widened registry read", async () => {
    const d18Bytes = assembleHeif({
      majorBrand: "mif1",
      compatibleBrands: ["miaf", "MA1B", "avif"],
      twoPass: true,
    });
    const directory = await freshDirectory();
    const d18Path = join(directory, "d18-brand.bin");
    await writeBytesTo(d18Path, d18Bytes);

    for (const path of [HEIC_PATH, AVIF_PATH, d18Path]) {
      const { counters, restore } = installTestHandlerAdditively();
      try {
        const inspected = await inspectFile(path);
        expect(inspected.ok).toBe(true);
        expect(counters.admit).toBe(1);
        expect(counters.buildOutputPlan).toBe(0);
        expect(counters.checkOutputPlan).toBe(0);
        expect(counters.writeOutput).toBe(0);
        expect(counters.verifyOutput).toBe(0);
      } finally {
        restore();
      }
    }
  });

  it("existing-format routing: webp/png/jpeg fixtures still select their own real handler while the ISOBMFF test handler is installed", async () => {
    const cases: readonly {
      readonly name: string;
      readonly bytes: Buffer;
      readonly handler: RegisteredHandler;
    }[] = [
      { name: "webp", bytes: metadataWebp(), handler: webpHandler },
      { name: "png", bytes: metadataPng(), handler: pngHandler },
      { name: "jpeg", bytes: metadataJpeg(), handler: jpegHandler },
    ];

    for (const { bytes, handler } of cases) {
      const directory = await freshDirectory();
      const path = join(directory, "input.bin");
      await writeFile(path, bytes);

      const { restore } = installTestHandlerAdditively();
      try {
        const selected = await selectThroughRealRegistry(path);
        expect(selected).toBe(handler);
      } finally {
        restore();
      }
    }
  });
});

